function buildLandingCertificateMarkup(c, fullView) {
  const logoHtml = LANDING_LG[c.n] || '';
  const code = c.code || ('PW-' + c.n.slice(0, 2).toUpperCase() + '-2026');
  const descKey = c.descKey || 'lp_ce_p';
  const t = function(k, fallback) {
    return (window.aloI18n && typeof window.aloI18n.t === 'function') ? window.aloI18n.t(k) : (fallback || '');
  };
  const metaHtml = fullView
    ? '<div class="lp-cert-meta">' +
        '<div><span data-i18n="lp_cert_ref_label">' + t('lp_cert_ref_label', 'Certificate ID') + '</span><strong class="notranslate">' + code + '</strong></div>' +
        '<div><span data-i18n="lp_cert_year_label">' + t('lp_cert_year_label', 'Year') + '</span><strong class="notranslate">2026</strong></div>' +
        '<div><span data-i18n="lp_cert_auth">' + t('lp_cert_auth', 'Authorized Program') + '</span><strong data-i18n="lp_cert_status">' + t('lp_cert_status', 'Active Partner') + '</strong></div>' +
      '</div>'
    : '';
  const footHtml = fullView
    ? '<div class="lp-cert-foot">' +
        '<div class="lp-cert-sign notranslate">PW NEW MEDIA<span data-i18n="lp_cert_auth">' + t('lp_cert_auth', 'Authorized Program') + '</span></div>' +
        '<span class="lp-cert-seal" data-i18n="lp_cert_status">' + t('lp_cert_status', 'Active Partner') + '</span>' +
      '</div>'
    : '<div class="lp-cert-foot">' +
        '<span class="lp-cert-ref notranslate">' + code + '</span>' +
        '<span class="lp-cert-seal" data-i18n="lp_cert_status">' + t('lp_cert_status', 'Active Partner') + '</span>' +
      '</div>';

  return (
    '<div class="' + (fullView ? 'lp-cert-full' : 'lp-cert-mini') + '">' +
      '<div class="lp-cert-top">' +
        '<span class="lp-cert-pair notranslate" dir="ltr">' + logoHtml + '<span>PW NEW MEDIA</span><i>×</i><span>' + c.n + '</span></span>' +
        '<span class="lp-cert-kicker" data-i18n="lp_cert_badge">' + t('lp_cert_badge', 'OFFICIAL COLLABORATION') + '</span>' +
      '</div>' +
      '<div class="lp-cert-body">' +
        '<strong data-i18n="lp_cert_title">' + t('lp_cert_title', 'Media Campaign Partner') + '</strong>' +
        '<div class="lp-cert-rule" aria-hidden="true"></div>' +
        '<p data-i18n="' + descKey + '">' + t(descKey, '') + '</p>' +
      '</div>' +
      metaHtml +
      footHtml +
    '</div>'
  );
}

function renderLandingCertificates() {
  const cg = document.getElementById('landing-cg');
  const lb = document.getElementById('landing-lb');
  if (!cg) return;
  cg.innerHTML = '';
  (window.CERTS || CERTS).forEach(function(c) {
    const b = document.createElement('button');
    b.className = 'cs';
    b.type = 'button';
    b.innerHTML =
      '<div class="cf">' +
      (c.src ? '<img alt="' + c.n + '" src="' + c.src + '">' : buildLandingCertificateMarkup(c, false)) +
      '</div><b>' + (LANDING_LG[c.n] || '') + '<span class="notranslate">' + c.n + '</span></b>';
    b.onclick = function() {
      if (!lb) return;
      lb.innerHTML = c.src
        ? '<img alt="' + c.n + '" src="' + c.src + '">'
        : buildLandingCertificateMarkup(c, true);
      lb.hidden = false;
    };
    cg.appendChild(b);
  });

  if (lb && !lb.dataset.lbBound) {
    lb.dataset.lbBound = 'true';
    lb.addEventListener('click', function() {
      lb.hidden = true;
      lb.innerHTML = '';
    });
  }

  document.querySelectorAll('#landing-view [data-landing-modal]').forEach(function(link) {
    if (link.dataset.modalBound) return;
    link.dataset.modalBound = 'true';
    link.addEventListener('click', function(e) {
      e.preventDefault();
      if (!lb || !window.aloI18n) return;
      const type = link.getAttribute('data-landing-modal');
      const titleKey = type === 'terms' ? 'lp_terms' : (type === 'priv' ? 'lp_priv' : 'lp_sup');
      const bodyKey = type === 'terms' ? 'lp_terms_body' : (type === 'priv' ? 'lp_priv_body' : 'lp_sup_body');
      const titleText = window.aloI18n.t(titleKey);
      const bodyText = window.aloI18n.t(bodyKey);
      lb.innerHTML = '';
      const box = document.createElement('div');
      const titleNode = document.createElement('span');
      titleNode.textContent = titleText;
      const bodyNode = document.createElement('p');
      bodyNode.textContent = bodyText;
      box.appendChild(titleNode);
      box.appendChild(bodyNode);
      lb.appendChild(box);
      lb.hidden = false;
    });
  });
}
window.renderLandingCertificates = renderLandingCertificates;

const viewOrder = { landing: 0, home: 0, login: 1, register: 2, dashboard: 3 };
let viewTransitionTimer = null;
let viewsReady = false;

function showView(viewName, style) {
  if (viewName === 'landing' || viewName === 'home') {
    const user = getCurrentUser();
    if (user) {
      showView('dashboard');
      openDashboardPanel('home');
      return;
    }
    viewName = 'landing';
  }
  const nextView = viewIds.includes(viewName) ? viewName : 'landing';
  const nextEl = document.getElementById(nextView + '-view');
  const allViews = Array.from(document.querySelectorAll('.page-view'));
  const currentEl = allViews.find(function(view) { return !view.hidden; });
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const applyHidden = function() {
    allViews.forEach(function(view) { view.hidden = view.id !== nextView + '-view'; });
    document.documentElement.classList.toggle('landing-active', nextView === 'landing');
    if (nextView === 'landing') {
      renderLandingCertificates();
    }
    if (window.aloI18n && typeof window.aloI18n.translateDOM === 'function') {
      window.aloI18n.translateDOM();
    }
  };

  if (nextView === 'register') {
    const pendingCode = sessionStorage.getItem('alo_pending_invite_code') || localStorage.getItem('alo_pending_invite_code');
    const regInviteInput = document.getElementById('register-invite-code');
    if (pendingCode && regInviteInput && !regInviteInput.value) {
      regInviteInput.value = pendingCode;
    }
  }

  window.clearTimeout(viewTransitionTimer);
  allViews.forEach(function(view) {
    view.classList.remove('view-leave', 'view-enter-forward', 'view-enter-back', 'view-enter-zoom');
  });
  document.documentElement.classList.remove('is-view-transitioning');

  if (currentEl === nextEl) {
    return;
  }

  if (!viewsReady || !currentEl || reduceMotion) {
    viewsReady = true;
    applyHidden();
    forceScrollToTop();
    return;
  }

  const currentName = currentEl.id.replace('-view', '');
  const enterClass = style === 'zoom'
    ? 'view-enter-zoom'
    : ((viewOrder[nextView] || 0) >= (viewOrder[currentName] || 0) ? 'view-enter-forward' : 'view-enter-back');

  document.documentElement.classList.add('is-view-transitioning');
  currentEl.classList.add('view-leave');
  viewTransitionTimer = window.setTimeout(function() {
    currentEl.classList.remove('view-leave');
    applyHidden();
    forceScrollToTop();
    nextEl.classList.add(enterClass);
    viewTransitionTimer = window.setTimeout(function() {
      nextEl.classList.remove(enterClass);
      document.documentElement.classList.remove('is-view-transitioning');
    }, style === 'zoom' ? 1500 : 560);
  }, 230);
}

function playLoginSuccess(name, onDone) {
  const user = getCurrentUser();
  const lang = getActiveLang(user);
  const titleTxt = tLang(lang, 'লগইন সফল!', 'Login Successful!', 'تم تسجيل الدخول بنجاح!');
  const subTxt = tLang(lang, 'PW New Media প্ল্যাটফর্মে স্বাগতম', 'Welcome to PW New Media', 'مرحباً بك في منصة PW New Media');
  const overlay = document.createElement('div');
  overlay.className = 'login-success-overlay';
  overlay.setAttribute('role', 'status');
  overlay.setAttribute('aria-live', 'polite');
  overlay.innerHTML =
    '<div class="login-success-box">' +
      '<svg class="login-success-ring" viewBox="0 0 110 110" aria-hidden="true">' +
        '<circle cx="55" cy="55" r="48"></circle>' +
        '<path d="M34 57 L49 72 L77 40"></path>' +
      '</svg>' +
      '<h2>' + titleTxt + '</h2>' +
      '<p>' + subTxt + '</p>' +
      '<div class="login-success-bar"><i></i></div>' +
    '</div>';
  document.body.appendChild(overlay);
  requestAnimationFrame(function() { overlay.classList.add('is-visible'); });

  window.setTimeout(function() {
    onDone();
    overlay.classList.add('is-leaving');
    window.setTimeout(function() { overlay.remove(); }, 460);
  }, 1900);
}

document.addEventListener('click', function(event) {
  const target = event.target.closest('.auth-button, button[type="submit"], .phone-register-submit');
  if (!target || target.disabled) return;
  if (window.getComputedStyle(target).position === 'static') target.style.position = 'relative';
  target.style.overflow = 'hidden';
  const rect = target.getBoundingClientRect();
  const size = Math.max(rect.width, rect.height) * 2;
  const dot = document.createElement('span');
  dot.className = 'btn-ripple-dot';
  dot.style.width = dot.style.height = size + 'px';
  dot.style.left = (event.clientX - rect.left - size / 2) + 'px';
  dot.style.top = (event.clientY - rect.top - size / 2) + 'px';
  target.appendChild(dot);
  window.setTimeout(function() { dot.remove(); }, 660);
});

function renderInvitePage() {
  const qrContainer = document.getElementById('invite-page-qr');
  const linkElement = document.getElementById('invite-page-link');
  const linkInput = document.getElementById('invite-link-input');
  const linkDisplay = document.getElementById('invite-link-display');
  const friendAccountEl = document.getElementById('invite-friend-account');
  const codeElement = document.getElementById('invite-page-code');
  if (!qrContainer) return;

  let user = null;
  try {
    user = JSON.parse(localStorage.getItem('aloSignedInUser') || 'null');
  } catch (error) {
    user = null;
  }

  const immediateReferrer = (user && user.superiorPhone && user.superiorPhone !== '11')
    ? user.superiorPhone
    : ((user && user.superiorId && user.superiorId !== '11') ? user.superiorId : '');
  if (friendAccountEl) {
    friendAccountEl.textContent = immediateReferrer || '—';
  }
  if (user && friendAccountEl) {
    const expectedPhone = normalizeBdPhone(user.phone || user.accountNumber);
    resolveReferrerAccountNumber(user).then(function(resolvedRefAccount) {
      try {
        const current = JSON.parse(localStorage.getItem('aloSignedInUser') || 'null');
        const currentPhone = current ? normalizeBdPhone(current.phone || current.accountNumber) : '';
        if (!current || (expectedPhone && currentPhone !== expectedPhone)) return;

        const targetEl = document.getElementById('invite-friend-account');
        if (resolvedRefAccount) {
          if (targetEl) targetEl.textContent = resolvedRefAccount;
          if (current.superiorPhone !== resolvedRefAccount) {
            current.superiorPhone = resolvedRefAccount;
            localStorage.setItem('aloSignedInUser', JSON.stringify(current));
          }
        } else if (targetEl) {
          const fallbackVal = (current.superiorId && current.superiorId !== '11') ? current.superiorId : '';
          targetEl.textContent = fallbackVal || '—';
        }
      } catch (e) {}
    });
  }

  const inviteCode = (user && (user.inviteCode || user.accountNumber)) || '';
  
  // Real working invite link with query parameter
  let inviteLink = '';
  if (inviteCode) {
    if (window.location.origin && window.location.origin !== 'null') {
      inviteLink = `${window.location.origin}/?invite=${encodeURIComponent(inviteCode)}`;
    } else {
      inviteLink = `https://${window.location.host || 'rf-media.vercel.app'}/?invite=${encodeURIComponent(inviteCode)}`;
    }
  }

  if (codeElement) codeElement.textContent = inviteCode || '—';
  if (linkElement) {
    linkElement.href = inviteLink;
    linkElement.textContent = inviteLink;
  }
  if (linkInput) {
    linkInput.value = inviteLink;
  }
  const activeLang = getActiveLang(user);
  if (linkDisplay) {
    linkDisplay.textContent = inviteLink || (inviteCode ? '' : tLang(
      activeLang,
      'আমন্ত্রণ লিঙ্ক পেতে আগে লগইন করুন।',
      'Please log in first to get your invite link.',
      'يرجى تسجيل الدخول أولاً للحصول على رابط الدعوة الخاص بك.'
    ));
  }
  const companyLinkDisplay = document.getElementById('invite-company-link-display');
  if (companyLinkDisplay) {
    companyLinkDisplay.textContent = inviteLink;
    companyLinkDisplay.title = tLang(activeLang, 'ক্লিক করে কপি করুন', 'Click to copy', 'انقر للنسخ');
  }

  qrContainer.replaceChildren();

  if (window.QRCode && inviteCode) {
    new QRCode(qrContainer, {
      text: inviteLink,
      width: 136,
      height: 136,
      colorDark: '#071638',
      colorLight: '#ffffff',
      correctLevel: QRCode.CorrectLevel.H
    });
  } else {
    qrContainer.textContent = inviteCode
      ? tLang(activeLang, 'QR কোড তৈরি করা যায়নি।', 'Unable to generate QR code.', 'تعذر إنشاء رمز QR.')
      : tLang(activeLang, 'আমন্ত্রণ কোড পেতে আগে লগইন করুন।', 'Please log in first to get your invite code.', 'يرجى تسجيل الدخول أولاً للحصول على رمز الدعوة.');
  }

  // Reset summary numbers immediately before async fetch so no previous account data lingers
  const initTotEl = document.getElementById('invite-total-commission');
  const initTodayEl = document.getElementById('invite-today-commission');
  const initCountEl = document.getElementById('invite-team-members-count');
  const initNewEl = document.getElementById('invite-today-new-count');
  if (initTotEl) initTotEl.textContent = '0.00';
  if (initTodayEl) initTodayEl.textContent = '0.00';
  if (initCountEl) initCountEl.textContent = '0';
  if (initNewEl) initNewEl.textContent = '0';

  // Populate dynamic Top Commission summary card from real commission transactions + 6%/2%/1% package & 3%/2%/1% daily task rates
  try {
    const phone = (user && (user.phone || user.accountNumber)) || '';
    const expectedNormPhone = normalizeBdPhone(phone);
    const ownerCreatedMs = (user && user.createdAt) ? new Date(user.createdAt).getTime() : NaN;
    const minValidTxTs = !isNaN(ownerCreatedMs) ? (ownerCreatedMs - 60000) : null;
    if (!phone) {
      renderInviteVipSalaryCards();
      return;
    }
    Promise.all([
      dbGetRealTeam(phone),
      dbGetTransactions(phone, 'commission').catch(function() { return []; })
    ]).then(function(results) {
      const activeAfter = getCurrentUser();
      const activeNormAfter = activeAfter ? normalizeBdPhone(activeAfter.phone || activeAfter.accountNumber) : '';
      if (expectedNormPhone && activeNormAfter !== expectedNormPhone) return;

      const teamData = results[0];
      const commTxs = Array.isArray(results[1]) ? results[1] : [];
      const allMembers = (teamData && teamData.all) || [];
      const totalMembers = allMembers.length;

      const teamCountEl = document.getElementById('invite-team-members-count');
      if (teamCountEl) teamCountEl.textContent = String(totalMembers);

      const nowObj = new Date();
      const nowDateStr = nowObj.toDateString();
      const todayLocalIso = `${nowObj.getFullYear()}-${String(nowObj.getMonth() + 1).padStart(2, '0')}-${String(nowObj.getDate()).padStart(2, '0')}`;
      const todayNew = allMembers.filter(function(m) {
        return m.joinedAt && new Date(m.joinedAt).toDateString() === nowDateStr;
      }).length;
      const todayNewEl = document.getElementById('invite-today-new-count');
      if (todayNewEl) todayNewEl.textContent = String(todayNew);

      const viewerCurr = getUserCurrency(user);

      // 1. Expected / team-derived commission breakdown (Package: 6%/2%/1%, Daily Task: 3%/2%/1%)
      let teamPkgCommTotal = 0;
      let teamPkgCommToday = 0;
      let teamTaskCommTotal = 0;
      let teamTaskCommToday = 0;

      allMembers.forEach(function(m) {
        const tierNum = Number(m.tier) || 1;
        const pkgRate = PACKAGE_COMMISSION_RATES[tierNum] || 0;
        const taskRate = DAILY_TASK_COMMISSION_RATES[tierNum] || 0;

        // Package spend in member currency -> viewer currency
        let pkgSpendRaw = Number(m.packageSpendTotal) || 0;
        if (pkgSpendRaw <= 0 && typeof packageData === 'object') {
          const paidPkgs = Array.isArray(m.purchasedPackages) ? m.purchasedPackages : (m.level && m.level !== 'LV0' ? [m.level] : []);
          const uniquePaid = Array.from(new Set(paidPkgs.map(function(p) { return String(p || '').toUpperCase().trim(); })))
            .filter(function(p) { return p && p !== 'LV0' && packageData[p] && Number(packageData[p].price) > 0; });
          const memberIsUsd = String(m.currency || 'BDT').toUpperCase() === 'USD';
          pkgSpendRaw = uniquePaid.reduce(function(sum, lvl) {
            const bdtPrice = Number(packageData[lvl].price) || 0;
            return sum + (memberIsUsd ? convertBetweenCurrencies(bdtPrice, 'BDT', 'USD') : bdtPrice);
          }, 0);
        }
        const pkgSpend = convertBetweenCurrencies(pkgSpendRaw, m.currency || 'BDT', viewerCurr);
        const pkgSpendToday = convertBetweenCurrencies(Number(m.packageSpendToday) || 0, m.currency || 'BDT', viewerCurr);

        // Paid task earnings in member currency -> viewer currency (avoid falling back to totalIncome when tx history loaded)
        const memberHasPaidLvl = String(m.level || 'LV0').toUpperCase() !== 'LV0' ||
          (Array.isArray(m.purchasedPackages) && m.purchasedPackages.some(function(p) { return String(p || '').toUpperCase() !== 'LV0'; }));
        const taskEarnRaw = m._hasTxLoaded
          ? (Number(m.taskEarningsTotal) || 0)
          : (Number(m.taskEarningsTotal) || (memberHasPaidLvl ? (Number(m.totalIncome) || 0) : 0));
        const taskEarnTodayRaw = Number(m.taskEarningsToday) || 0;
        const taskEarn = convertBetweenCurrencies(taskEarnRaw, m.currency || 'BDT', viewerCurr);
        const taskEarnToday = convertBetweenCurrencies(taskEarnTodayRaw, m.currency || 'BDT', viewerCurr);

        teamPkgCommTotal += Math.round(pkgSpend * pkgRate * 100) / 100;
        teamPkgCommToday += Math.round(pkgSpendToday * pkgRate * 100) / 100;
        teamTaskCommTotal += Math.round(taskEarn * taskRate * 100) / 100;
        teamTaskCommToday += Math.round(taskEarnToday * taskRate * 100) / 100;
      });

      // 2. Authoritative team commission ledger transactions (exclude Lucky Spin prizes & pre-creation rows!)
      let txPkgTotal = 0;
      let txTaskTotal = 0;
      let txOtherTotal = 0;
      let txTodayPkgTaskTotal = 0;
      let txTodayOtherTotal = 0;

      commTxs.forEach(function(tx) {
        if (minValidTxTs !== null && tx.createdAt) {
          const txTs = new Date(tx.createdAt).getTime();
          if (!isNaN(txTs) && txTs < minValidTxTs) return;
        }
        const st = String(tx.status || '').toLowerCase();
        if (st.includes('reject') || st.includes('বাতিল') || st.includes('fail') || st.includes('অসফল')) return;
        const amt = Number(tx.actual || tx.amount || 0);
        if (amt <= 0) return;
        const methodStr = String(tx.method || '').toLowerCase();
        // Exclude Lucky Spin rewards recorded under type='commission'
        if (methodStr.includes('lucky spin') || methodStr.includes('ভাগ্যবান স্পিন') || methodStr.includes('লটারি')) {
          return;
        }
        const isPkgTx = methodStr.includes('প্যাকেজ') || methodStr.includes('package');
        const isTaskTx = methodStr.includes('দৈনিক') || methodStr.includes('task') || methodStr.includes('কাজের');
        if (isPkgTx) txPkgTotal += amt;
        else if (isTaskTx) txTaskTotal += amt;
        else txOtherTotal += amt;

        const isTodayTx = tx.createdAt
          ? (new Date(tx.createdAt).toDateString() === nowDateStr)
          : Boolean(tx.date && String(tx.date) === todayLocalIso);
        if (isTodayTx) {
          if (isPkgTx || isTaskTx) txTodayPkgTaskTotal += amt;
          else txTodayOtherTotal += amt;
        }
      });

      const totalComm = Math.max(txPkgTotal, teamPkgCommTotal) + Math.max(txTaskTotal, teamTaskCommTotal) + txOtherTotal;
      const todayComm = Math.max(txTodayPkgTaskTotal, teamPkgCommToday + teamTaskCommToday) + txTodayOtherTotal;

      const totCommEl = document.getElementById('invite-total-commission');
      if (totCommEl) totCommEl.textContent = totalComm.toFixed(2);
      const todayCommEl = document.getElementById('invite-today-commission');
      if (todayCommEl) todayCommEl.textContent = todayComm.toFixed(2);
    }).catch(function() {});
  } catch(e) {}

  // Render dynamic VIP Salary & Upgrade Level progress and buttons
  renderInviteVipSalaryCards();
}

async function renderInviteVipSalaryCards() {
  const container = document.getElementById('invite-vip-salary-cards-container');
  if (!container) return;

  const user = getCurrentUser();
  const isUsd = isUsdOnlyUser(user);
  const sym = getUserCurrencySymbol(user);
  const lang = getActiveLang(user);
  const phone = (user && (user.phone || user.accountNumber)) || '';
  const expectedNormPhone = normalizeBdPhone(phone);
  // Salary progression counts ONLY A-Level (Tier 1) active members who purchased a paid package (LV1+)
  let activeTier1Count = 0;

  try {
    const teamData = await dbGetRealTeam(phone);
    const activeAfter = getCurrentUser();
    const activeNormAfter = activeAfter ? normalizeBdPhone(activeAfter.phone || activeAfter.accountNumber) : '';
    if (expectedNormPhone && activeNormAfter !== expectedNormPhone) return;
    const tier1List = (teamData && Array.isArray(teamData.tier1)) ? teamData.tier1 : [];
    activeTier1Count = tier1List.filter(isPaidActiveTeamMember).length;
  } catch(e) {
    activeTier1Count = 0;
  }

  const activeALabelEl = document.getElementById('salary-active-a-label');
  const activeACountEl = document.getElementById('salary-active-a-count');
  const activeAUnitEl = document.getElementById('salary-active-a-unit');
  if (activeALabelEl) {
    activeALabelEl.textContent = tLang(
      lang,
      'সক্রিয় A-লেভেল সদস্য (প্যাকেজ ক্রয়কৃত):',
      'Active A-Level Members (Paid):',
      'أعضاء المستوى A النشطون (باقة مدفوعة):'
    );
  }
  if (activeACountEl) {
    activeACountEl.textContent = lang === 'bn' ? formatBanglaNumber(activeTier1Count) : String(activeTier1Count);
  }
  if (activeAUnitEl) {
    activeAUnitEl.textContent = tLang(lang, 'জন', 'Members', 'عضو');
  }

  let claimed = (user && Array.isArray(user.claimedInviteRewards)) ? user.claimedInviteRewards : [];
  if (claimed.length === 0) {
    try {
      claimed = JSON.parse(localStorage.getItem('alo_claimed_invite_rewards') || '[]');
    } catch(e) {
      claimed = [];
    }
  }

  const tiersConfig = [
    { tier: 'অবস্থান ১', tierEn: 'Position 1', tierAr: 'المركز 1', req: 3, salary: 1000, label: '৳ ১,০০০' },
    { tier: 'অবস্থান ২', tierEn: 'Position 2', tierAr: 'المركز 2', req: 5, salary: 1800, label: '৳ ১,৮০০' },
    { tier: 'অবস্থান ৩', tierEn: 'Position 3', tierAr: 'المركز 3', req: 8, salary: 2500, label: '৳ ২,৫০০' },
    { tier: 'অবস্থান ৪', tierEn: 'Position 4', tierAr: 'المركز 4', req: 15, salary: 3200, label: '৳ ৩,২০০' },
    { tier: 'অবস্থান ৫', tierEn: 'Position 5', tierAr: 'المركز 5', req: 25, salary: 4000, label: '৳ ৪,০০০' },
    { tier: 'অবস্থান ৬', tierEn: 'Position 6', tierAr: 'المركز 6', req: 40, salary: 5500, label: '৳ ৫,৫০০' },
    { tier: 'অবস্থান ৭', tierEn: 'Position 7', tierAr: 'المركز 7', req: 70, salary: 7000, label: '৳ ৭,০০০' },
    { tier: 'অবস্থান ৮', tierEn: 'Position 8', tierAr: 'المركز 8', req: 100, salary: 10000, label: '৳ ১০,০০০' }
  ];

  tiersConfig.forEach(function(cfg) {
    const effectiveCount = activeTier1Count;

    const rewardAmt = toUserCurrencyAmount(cfg.salary, user);
    const displayLabel = isUsd
      ? `${sym}${rewardAmt.toFixed(2)}`
      : (lang === 'bn' ? cfg.label : `৳ ${cfg.salary.toLocaleString('en-US')}`);
    const salaryKey = `${cfg.tier}-salary`;
    const isClaimed = claimed.includes(salaryKey);
    const isUnlocked = effectiveCount >= cfg.req;
    const pct = Math.min(100, Math.floor((effectiveCount / cfg.req) * 100));

    // Update real progress bar and percentage text in the row
    const row = document.querySelector(`.salary-row[data-vip-tier="${cfg.tier}"]`);
    if (row) {
      const posEl = row.querySelector('.salary-pos');
      if (posEl) posEl.textContent = tLang(lang, cfg.tier, cfg.tierEn, cfg.tierAr);
      const fillEl = row.querySelector('.fill');
      if (fillEl) fillEl.style.width = `${pct}%`;
      const pctEl = row.querySelector('.pct');
      if (pctEl) pctEl.textContent = lang === 'bn' ? `${formatBanglaNumber(pct)}%` : `${pct}%`;
      const progWrap = row.querySelector('.prog');
      if (progWrap) {
        let countBadge = row.querySelector('.salary-count-ratio');
        if (!countBadge) {
          countBadge = document.createElement('div');
          countBadge.className = 'salary-count-ratio text-[10.5px] text-[#38bdf8] font-mono font-semibold mt-0.5';
          progWrap.parentNode.appendChild(countBadge);
        }
        const curShow = Math.min(effectiveCount, cfg.req);
        countBadge.textContent = lang === 'bn'
          ? `${formatBanglaNumber(curShow)} / ${formatBanglaNumber(cfg.req)} জন`
          : `${curShow} / ${cfg.req}`;
      }
      if (isUnlocked) {
        row.classList.add('done');
      } else {
        row.classList.remove('done');
      }
    }

    const salaryBtn = document.querySelector(`.salary-pay[data-vip-tier="${cfg.tier}"][data-reward-type="salary"], .invite-claim-btn[data-vip-tier="${cfg.tier}"][data-reward-type="salary"]`);
    if (salaryBtn) {
      salaryBtn.dataset.currentCount = String(effectiveCount);
      salaryBtn.dataset.requiredMembers = String(cfg.req);
      salaryBtn.dataset.rewardAmount = String(rewardAmt);

      if (isClaimed) {
        salaryBtn.dataset.isClaimed = 'true';
        salaryBtn.dataset.isUnlocked = 'false';
        salaryBtn.style.setProperty('background', '#059669', 'important');
        salaryBtn.style.setProperty('color', '#ffffff', 'important');
        salaryBtn.style.setProperty('filter', 'none', 'important');
        salaryBtn.style.setProperty('opacity', '1', 'important');
        salaryBtn.style.setProperty('cursor', 'default', 'important');
        salaryBtn.style.setProperty('box-shadow', 'none', 'important');
        salaryBtn.classList.remove('animate-pulse');
        salaryBtn.innerHTML = `
          <small class="block text-[10.5px] font-semibold leading-tight text-white">${tLang(lang, 'গৃহীত ✓', 'Claimed ✓', 'تم الاستلام ✓')}</small>
          <strong class="block text-[16px] font-bold font-mono leading-tight text-white">${displayLabel}</strong>
        `;
      } else if (isUnlocked) {
        salaryBtn.dataset.isClaimed = 'false';
        salaryBtn.dataset.isUnlocked = 'true';
        salaryBtn.style.setProperty('background', '#1877f2', 'important');
        salaryBtn.style.setProperty('color', '#ffffff', 'important');
        salaryBtn.style.setProperty('filter', 'none', 'important');
        salaryBtn.style.setProperty('opacity', '1', 'important');
        salaryBtn.style.setProperty('cursor', 'pointer', 'important');
        salaryBtn.style.setProperty('box-shadow', 'none', 'important');
        salaryBtn.classList.remove('animate-pulse');
        salaryBtn.innerHTML = `
          <small class="block text-[10.5px] font-semibold leading-tight text-white">${tLang(lang, 'গ্রহণ করুন', 'Claim', 'استلام')}</small>
          <strong class="block text-[16px] font-bold font-mono leading-tight text-white">${displayLabel}</strong>
        `;
      } else {
        salaryBtn.dataset.isClaimed = 'false';
        salaryBtn.dataset.isUnlocked = 'false';
        salaryBtn.style.setProperty('background', '#071638', 'important');
        salaryBtn.style.setProperty('color', '#e5e7eb', 'important');
        salaryBtn.style.setProperty('filter', 'none', 'important');
        salaryBtn.style.setProperty('opacity', '1', 'important');
        salaryBtn.style.setProperty('cursor', 'pointer', 'important');
        salaryBtn.style.setProperty('box-shadow', 'none', 'important');
        salaryBtn.classList.remove('animate-pulse');
        salaryBtn.innerHTML = `
          <small class="block text-[10.5px] font-semibold leading-tight text-[#e5e7eb]">${tLang(lang, '🔒 মাসিক বেতন', '🔒 Monthly Salary', '🔒 الراتب الشهري')}</small>
          <strong class="block text-[16px] font-bold font-mono leading-tight text-[#f3f4f6]">${displayLabel}</strong>
        `;
      }
    }
  });
}
window.renderInviteVipSalaryCards = renderInviteVipSalaryCards;

// Clean 2-tier button HTML with pure bold CTA without icons
function renderInviteButtonHTML(type, amount, isClaimed, isUnlocked) {
  const user = getCurrentUser();
  const sym = getUserCurrencySymbol(user);
  const lang = getActiveLang(user);
  const typeLabel = type === 'salary'
    ? tLang(lang, 'মাসিক বেতন', 'Monthly Salary', 'الراتب الشهري')
    : tLang(lang, 'নগদ বোনাস', 'Cash Bonus', 'مكافأة نقدية');
  const amtFormatted = sym + ' ' + Number(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  if (isClaimed) {
    return `
      <span class="invite-btn-top">${typeLabel} ${amtFormatted}</span>
      <span class="invite-btn-main text-emerald-400 font-bold">${tLang(lang, 'গৃহীত', 'Claimed', 'تم الاستلام')}</span>
    `;
  }
  if (isUnlocked) {
    return `
      <span class="invite-btn-top">${typeLabel} ${amtFormatted}</span>
      <span class="invite-btn-main font-extrabold text-white">${tLang(lang, 'গ্রহণ করুন', 'Claim', 'استلام')}</span>
    `;
  }
  return `
    <span class="invite-btn-top">${typeLabel} ${amtFormatted}</span>
    <span class="invite-btn-main">${tLang(lang, 'গ্রহণ করুন', 'Claim', 'استلام')}</span>
  `;
}
window.renderInviteButtonHTML = renderInviteButtonHTML;

// REAL VIP SALARY & BONUS ACTIVATION & CLAIM MODAL SYSTEM
let currentInviteClaim = null;

function openInviteVipClaimModal(tier, type, amount, reqMembers, currentCount) {
  const curUser = getCurrentUser();
  const sym = getUserCurrencySymbol(curUser);
  const lang = getActiveLang(curUser);

  currentInviteClaim = {
    tier: tier,
    type: type,
    amount: Number(amount) || 0,
    reqMembers: Number(reqMembers) || 1,
    currentCount: Number(currentCount) || 0,
    key: `${tier}-${type}`
  };

  const modal = document.getElementById('invite-vip-claim-modal');
  if (!modal) return;

  const tierDisp = getVipTierLabel(tier, lang);
  const typeName = type === 'salary'
    ? tLang(lang, 'মাসিক বেতন', 'Monthly Salary', 'الراتب الشهري')
    : tLang(lang, 'নগদ পুরস্কার', 'Cash Bonus', 'مكافأة نقدية');
  const titleEl = document.getElementById('invite-modal-tier-title');
  if (titleEl) titleEl.textContent = `${tierDisp} (${typeName})`;

  const typeEl = document.getElementById('invite-modal-reward-type');
  if (typeEl) typeEl.textContent = tLang(lang, 'নির্ধারিত লক্ষ্য পূরণ বেতন', 'Target Achievement Salary', 'راتب تحقيق الهدف');

  const amtEl = document.getElementById('invite-modal-amount-display');
  if (amtEl) amtEl.textContent = `${sym} ` + Number(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  const reqEl = document.getElementById('invite-modal-req-display');
  if (reqEl) reqEl.textContent = tLang(lang, `${reqMembers} জন সক্রিয় সদস্য`, `${reqMembers} Active Members`, `${reqMembers} أعضاء نشطين`);

  const curCount = Number(currentCount) || 0;
  const pct = Math.min(100, Math.round((curCount / reqMembers) * 100));
  const curEl = document.getElementById('invite-modal-current-display');
  if (curEl) {
    curEl.textContent = tLang(lang, `${curCount} / ${reqMembers} জন (${pct}%)`, `${curCount} / ${reqMembers} (${pct}%)`, `${curCount} / ${reqMembers} (${pct}%)`);
    curEl.className = pct >= 100 ? 'text-emerald-400 font-mono font-bold' : 'text-[#35c6e7] font-mono font-bold';
  }

  const barEl = document.getElementById('invite-modal-progress-bar');
  if (barEl) barEl.style.width = `${pct}%`;

  const claimBtn = document.getElementById('invite-modal-claim-btn');
  if (claimBtn) {
    const key = `${tier}-${type}`;
    let claimed = (curUser && Array.isArray(curUser.claimedInviteRewards)) ? curUser.claimedInviteRewards : [];
    if (claimed.length === 0) {
      try { claimed = JSON.parse(localStorage.getItem('alo_claimed_invite_rewards') || '[]'); } catch(e) {}
    }
    const isClaimed = claimed.includes(key);

    if (isClaimed) {
      claimBtn.disabled = true;
      claimBtn.className = 'w-full py-3.5 rounded-xl font-bold text-sm flex items-center justify-center bg-emerald-800/50 text-emerald-300 border border-emerald-600/40 cursor-not-allowed';
      claimBtn.innerHTML = `<span>${tLang(lang, '✓ এই বেতন ইতোমধ্যে গ্রহণ করা হয়েছে', '✓ Already Claimed', '✓ تم استلام هذا الراتب مسبقاً')}</span>`;
    } else if (curCount >= reqMembers) {
      claimBtn.disabled = false;
      claimBtn.className = 'w-full py-3.5 rounded-xl font-extrabold text-sm transition cursor-pointer active:scale-95 flex items-center justify-center bg-gradient-to-r from-emerald-500 to-teal-400 text-white shadow-xl shadow-emerald-500/30 animate-pulse';
      claimBtn.innerHTML = `<span>${tLang(
        lang,
        `মূল ব্যালেন্সে গ্রহণ করুন (${sym} ${Number(amount).toLocaleString()})`,
        `Claim to Balance (${sym}${Number(amount).toFixed(2)})`,
        `استلام إلى الرصيد (${sym}${Number(amount).toFixed(2)})`
      )}</span>`;
    } else {
      claimBtn.disabled = true;
      claimBtn.className = 'w-full py-3.5 rounded-xl font-bold text-sm flex items-center justify-center bg-slate-800/90 text-slate-400 border border-slate-700/60 cursor-not-allowed select-none';
      const needed = reqMembers - curCount;
      claimBtn.innerHTML = `<span>${tLang(
        lang,
        `🔒 শর্ত পূরণ হয়নি (আরো ${formatBanglaNumber(needed)} জন সক্রিয় সদস্য প্রয়োজন)`,
        `🔒 Locked (${needed} more active members needed)`,
        `🔒 مقفل (مطلوب ${needed} عضو نشط إضافي)`
      )}</span>`;
    }
  }

  modal.style.display = 'flex';
  modal.hidden = false;
  modal.classList.remove('hidden');
}
window.openInviteVipClaimModal = openInviteVipClaimModal;

function closeInviteVipClaimModal() {
  const modal = document.getElementById('invite-vip-claim-modal');
  if (modal) {
    modal.style.display = 'none';
    modal.hidden = true;
    modal.classList.add('hidden');
  }
  currentInviteClaim = null;
}
window.closeInviteVipClaimModal = closeInviteVipClaimModal;

let _isClaimingVipReward = false;
async function executeVipRewardClaim(tier, type, amount, reqMembers, currentCount) {
  if (_isClaimingVipReward) return;
  const user = getCurrentUser();
  const curLang = getActiveLang(user);
  if (!user || !(user.phone || user.accountNumber)) {
    showToastNotification(tLang(curLang, 'অনুগ্রহ করে প্রথমে লগইন করুন।', 'Please log in first.', 'يرجى تسجيل الدخول أولاً.'));
    return;
  }
  _isClaimingVipReward = true;
  try {
  const sym = getUserCurrencySymbol(user);
  const lang = getActiveLang(user);
  const tierDisp = getVipTierLabel(tier, lang);
  const key = `${tier}-${type}`;
  const normPhone = normalizeBdPhone(user.phone || user.accountNumber);

  // STRICT REAL VALIDATION: Re-verify live A-level active paid members from Supabase!
  let verifiedActiveCount = 0;
  try {
    if (typeof _realTeamCache !== 'undefined') _realTeamCache.delete(normPhone);
    const liveTeamData = await dbGetRealTeam(normPhone);
    const liveTier1 = (liveTeamData && Array.isArray(liveTeamData.tier1)) ? liveTeamData.tier1 : [];
    verifiedActiveCount = liveTier1.filter(isPaidActiveTeamMember).length;
  } catch(e) {
    verifiedActiveCount = 0;
  }

  if (verifiedActiveCount < Number(reqMembers)) {
    const needed = Number(reqMembers) - verifiedActiveCount;
    showToastNotification(tLang(
      lang,
      `⚠️ শর্ত পূরণ হয়নি! A-লেভেলে আরও ${formatBanglaNumber(needed)} জন প্যাকেজ কেনা সক্রিয় সদস্য প্রয়োজন (বর্তমান: ${formatBanglaNumber(verifiedActiveCount)}/${formatBanglaNumber(reqMembers)})`,
      `⚠️ Requirement not met! ${needed} more A-Level active member(s) with a paid package required (${verifiedActiveCount}/${reqMembers}).`,
      `⚠️ لم يتم استيفاء الشرط! مطلوب ${needed} عضو نشط إضافي في المستوى A اشترى باقة (${verifiedActiveCount}/${reqMembers}).`
    ));
    closeInviteVipClaimModal();
    await renderInviteVipSalaryCards();
    return;
  }

  // Re-verify live claim state and live balance from Supabase first
  const cloudUser = await dbGetUser(normPhone);
  const liveUser = cloudUser ? Object.assign({}, user, cloudUser) : user;
  let claimed = Array.isArray(liveUser.claimedInviteRewards) ? liveUser.claimedInviteRewards.slice() : [];

  if (claimed.includes(key)) {
    localStorage.setItem('alo_claimed_invite_rewards', JSON.stringify(claimed));
    showToastNotification(tLang(
      lang,
      `✓ আপনি ${tier} এর এই বোনাসটি ইতোমধ্যে গ্রহণ করেছেন!`,
      `✓ You have already claimed this ${tierDisp} reward!`,
      `✓ لقد استلمت مكافأة ${tierDisp} هذه مسبقاً!`
    ));
    closeInviteVipClaimModal();
    await renderInviteVipSalaryCards();
    return;
  }

  const prevBal = Number(liveUser.balance) || 0;
  const addAmt = Number(amount) || 0;
  const newBal = Number((prevBal + addAmt).toFixed(2));
  liveUser.balance = newBal;
  liveUser.totalIncome = Number(((Number(liveUser.totalIncome) || 0) + addAmt).toFixed(2));
  liveUser.todayIncome = Number(((Number(liveUser.todayIncome) || 0) + addAmt).toFixed(2));
  liveUser.lifetimeEarnings = Number(((Number(liveUser.lifetimeEarnings) || 0) + addAmt).toFixed(2));
  claimed.push(key);
  liveUser.claimedInviteRewards = claimed;

  localStorage.setItem('aloSignedInUser', JSON.stringify(liveUser));
  localStorage.setItem('my_pass_available_bal', newBal.toFixed(2));
  localStorage.setItem('alo_claimed_invite_rewards', JSON.stringify(claimed));

  await dbSaveUser(liveUser);

  const now = new Date();
  await dbRecordTransaction({
    phone: normPhone,
    type: 'vip_reward',
    amount: addAmt,
    ratio: '100%',
    actual: addAmt,
    status: 'অনুমোদিত',
    method: tLang(
      lang,
      `${tier} ${type === 'salary' ? 'মাসিক বেতন' : 'নগদ পুরস্কার'}`,
      `${tierDisp} ${type === 'salary' ? 'Monthly Salary' : 'Cash Reward'}`,
      `${tierDisp} ${type === 'salary' ? 'الراتب الشهري' : 'مكافأة نقدية'}`
    ),
    order_id: 'VIP' + Date.now() + Math.floor(100 + Math.random() * 900),
    date: now.toISOString().split('T')[0],
    time: now.toTimeString().split(' ')[0],
    newBalance: newBal
  });

  closeInviteVipClaimModal();
  updateUserDetails(liveUser);
  updateProfileMetrics();
  await renderInviteVipSalaryCards();

  const typeLabel = type === 'salary'
    ? tLang(lang, 'মাসিক বেতন', 'Monthly Salary', 'الراتب الشهري')
    : tLang(lang, 'নগদ পুরস্কার', 'Cash Reward', 'مكافأة نقدية');
  showToastNotification(tLang(
    lang,
    `🎉 অভিনন্দন! ${tier} ${typeLabel} ${sym} ${addAmt.toLocaleString()} সফলভাবে মূল ব্যালেন্সে যোগ হয়েছে!`,
    `🎉 Congratulations! ${sym}${addAmt.toFixed(2)} ${getUserCurrency(liveUser)} (${typeLabel}) added to your balance!`,
    `🎉 تهانينا! تم إضافة ${sym}${addAmt.toFixed(2)} ${getUserCurrency(liveUser)} (${typeLabel}) إلى رصيدك!`
  ));

  const balEl = document.getElementById('records-balance-display');
  if (balEl) {
    balEl.textContent = formatMoney(Number((newBal + (Number(liveUser.rechargeFrozenBalance) || 0)).toFixed(2)), liveUser);
    balEl.classList.add('scale-110', 'text-emerald-400');
    setTimeout(() => balEl.classList.remove('scale-110', 'text-emerald-400'), 1500);
  }
  } finally {
    _isClaimingVipReward = false;
  }
}
window.executeVipRewardClaim = executeVipRewardClaim;

function forceScrollToTop(targetPanelId) {
  const loginView = document.getElementById('login-view');
  const regView = document.getElementById('register-view');
  if ((loginView && !loginView.hidden) || (regView && !regView.hidden)) {
    return;
  }
  if (document.activeElement && typeof document.activeElement.blur === 'function') {
    try {
      document.activeElement.blur();
    } catch(e) {}
  }
  try {
    window.scrollTo({ top: 0, left: 0, behavior: 'instant' });
  } catch(e) {
    try { window.scrollTo(0, 0); } catch(e2) {}
  }
  if (document.scrollingElement) document.scrollingElement.scrollTop = 0;
  if (document.documentElement) document.documentElement.scrollTop = 0;
  if (document.body) document.body.scrollTop = 0;
  const shell = document.querySelector('.dashboard-shell');
  if (shell) shell.scrollTop = 0;
  const mainEl = document.querySelector('.dashboard-shell > main');
  if (mainEl) mainEl.scrollTop = 0;
  const dView = document.getElementById('dashboard-view');
  if (dView) dView.scrollTop = 0;
  const panel = targetPanelId ? document.getElementById(targetPanelId) : document.querySelector('.dashboard-panel:not([hidden])');
  if (panel) {
    panel.scrollTop = 0;
    try {
      panel.scrollIntoView({ block: 'start', inline: 'nearest', behavior: 'instant' });
    } catch(e) {}
  }
}

function openDashboardPanel(panelName) {
  if (panelName === "manager" || panelName === "customer-service") {
    panelName = "customer-service";
  }
  if (panelName === "my-team" || panelName === "team-members") {
    panelName = "team-report";
    window._autoSelectTeamTab = "members";
  } else if (panelName === "team-report") {
    window._autoSelectTeamTab = "report";
  }
  if (document.activeElement && typeof document.activeElement.blur === 'function') {
    try { document.activeElement.blur(); } catch(e) {}
  }
  forceScrollToTop(panelName + '-panel');
  const nextPanel = dashboardTitles[panelName] ? panelName : 'home';
  if (nextPanel !== 'payment-method' && nextPanel !== 'bd-recharge' && nextPanel !== 'team-report' && nextPanel !== 'withdraw' && nextPanel !== 'withdraw-details' && nextPanel !== 'customer-service' && nextPanel !== 'usdt-deposit') {
    previousDashboardPanel = nextPanel;
  }
  document.querySelectorAll('.dashboard-panel').forEach(function(panel) {
    panel.hidden = panel.id !== nextPanel + '-panel';
  });

  // Ensure bottom navigation bar is permanently visible on all pages as requested ("যেকোনো পেজে গেলেও নিচের আইকন থাকবে")
  const bottomNav = document.getElementById('dashboard-bottom-nav') || document.querySelector('nav[aria-label="প্রধান মেনু"]');
  if (bottomNav) {
    bottomNav.style.setProperty('display', 'grid', 'important');
    bottomNav.style.setProperty('visibility', 'visible', 'important');
    bottomNav.style.setProperty('opacity', '1', 'important');
    bottomNav.style.setProperty('pointer-events', 'auto', 'important');
    if (nextPanel === 'package-detail') {
      document.body.style.backgroundColor = '#030d24';
    } else {
      document.body.style.backgroundColor = '';
    }
  }

  if (nextPanel === 'usdt-deposit') {
    const detailsCard = document.getElementById('usdt-deposit-details-card');
    const preView = document.getElementById('usdt-pre-deposit-view');
    if (detailsCard) detailsCard.classList.add('hidden');
    if (preView) preView.classList.remove('hidden');
  }

  const navItemMap = {
    home: 'home',
    vip: 'vip',
    'platform-tasks': 'vip',
    records: 'records',
    'package-detail': 'records',
    tasks: 'tasks',
    'mission-submit': 'tasks',
    profile: 'profile',
    personal: 'profile',
    'my-pass': 'profile',
    'account-change': 'profile',
    invite: 'profile',
    'payment-method': 'profile',
    'usdt-deposit': 'profile',
    'team-report': 'profile',
    'team-members': 'profile',
    'my-team': 'profile',
    'savings-plan': 'profile',
    'lucky-spin': 'profile',
    'bkash-setup': 'profile',
    'nagad-setup': 'profile',
    'usdt-setup': 'profile',
    'realname-setup': 'profile',
    'fund-password-setup': 'profile',
    'customer-service': 'home',
    manager: 'home'
  };
  const activeNavKey = navItemMap[nextPanel] || nextPanel;
  document.querySelectorAll('.dashboard-nav-item').forEach(function(button) {
    button.removeAttribute('aria-current');
    if (button.dataset.panel === activeNavKey) {
      button.setAttribute('aria-current', 'page');
    }
  });
  const titleEl = document.getElementById('dashboard-title');
  if (titleEl) titleEl.textContent = dashboardTitles[nextPanel];
  if (nextPanel === 'home') {
    goToPWBannerSlide(0);
    startPWBannerAutoPlay();
  } else {
    stopPWBannerAutoPlay();
  }
  if (nextPanel === 'invite') {
    renderInvitePage();
  }
  if (nextPanel === 'savings-plan') {
    renderSavingsPlanPanel();
  }
  if (nextPanel === 'lucky-spin') {
    if (typeof renderLuckySpinPanel === 'function') renderLuckySpinPanel();
  }
  if (nextPanel === 'platform-tasks') {
    renderPackageTasks(activePackageLevel || 'LV0');
  }
  if (nextPanel === 'profile') {
    updateProfileMetrics();
    updateBkashDisplayAcrossApp(); updateNagadDisplayAcrossApp(); updateUsdtDisplayAcrossApp(); updateRealNameDisplayAcrossApp(); updateFundPasswordDisplayAcrossApp();
  }
  if (nextPanel === 'personal') {
    updateBkashDisplayAcrossApp(); updateNagadDisplayAcrossApp(); updateUsdtDisplayAcrossApp(); updateRealNameDisplayAcrossApp(); updateFundPasswordDisplayAcrossApp();
  }
  if (nextPanel === 'fund-password-setup') {
    renderFundPasswordSetupPanel();
  }
  if (nextPanel === 'bkash-setup') {
    renderBkashSetupPanel();
  }
  if (nextPanel === 'nagad-setup') {
    renderNagadSetupPanel();
  }
  if (nextPanel === 'usdt-setup') {
    renderUsdtSetupPanel();
  }
  if (nextPanel === 'realname-setup') {
    renderRealNameSetupPanel();
  }
  if (nextPanel === 'my-pass') {
    updateProfileMetrics();
    renderWithdrawalHistory();
    updateBkashDisplayAcrossApp(); updateNagadDisplayAcrossApp(); updateUsdtDisplayAcrossApp();
  }
  if (nextPanel === 'account-change') {
    updateProfileMetrics();
    if (typeof renderAccountChangeHistory === 'function') {
      renderAccountChangeHistory({ checkBackend: true });
    }
    if (typeof startAccountChangePolling === 'function') {
      startAccountChangePolling();
    }
  } else if (typeof stopAccountChangePolling === 'function') {
    stopAccountChangePolling();
  }
  if (nextPanel === 'vip') {
    if (typeof updateVipHallRooms === 'function') updateVipHallRooms();
    if (typeof loadPlatformConfigFromSupabase === 'function') loadPlatformConfigFromSupabase();
  }
  if (nextPanel === 'records') {
    if (typeof updateRecordsPanelPackages === 'function') updateRecordsPanelPackages();
    if (typeof loadPlatformConfigFromSupabase === 'function') loadPlatformConfigFromSupabase();
  }
  if (nextPanel === 'package-detail') {
    if (typeof loadPlatformConfigFromSupabase === 'function') loadPlatformConfigFromSupabase();
  }
  if (nextPanel === 'platform-tasks') {
    if (typeof loadPlatformConfigFromSupabase === 'function') loadPlatformConfigFromSupabase();
  }
  if (nextPanel === 'tasks') {
    renderMissionRecords(activeMissionFilter);
  }
  if (nextPanel === 'mission-submit') {
    renderMissionSubmission();
  }
  if (nextPanel === 'team-report') {
    const autoTab = window._autoSelectTeamTab || 'report';
    const reportTab = document.getElementById('team-tab-report');
    const membersTab = document.getElementById('team-tab-members');
    const reportContent = document.getElementById('team-report-view-content');
    const membersContent = document.getElementById('team-members-view-content');
    const headerTitle = document.getElementById('team-panel-header-title');

    const teamLang = getActiveLang(getCurrentUser());
    if (autoTab === 'members') {
      if (reportContent) reportContent.classList.add('hidden');
      if (membersContent) membersContent.classList.remove('hidden');
      if (headerTitle) headerTitle.textContent = tLang(teamLang, 'আমার দল', 'My Team', 'فريقي');

      if (reportTab) {
        reportTab.classList.remove('font-bold', 'text-[#38bdf8]');
        reportTab.classList.add('font-medium', 'text-slate-300');
        const ind = reportTab.querySelector('.team-tab-indicator');
        if (ind) { ind.classList.remove('bg-[#38bdf8]'); ind.classList.add('bg-transparent'); }
      }
      if (membersTab) {
        membersTab.classList.remove('font-medium', 'text-slate-300');
        membersTab.classList.add('font-bold', 'text-[#38bdf8]');
        const ind = membersTab.querySelector('.team-tab-indicator');
        if (ind) { ind.classList.remove('bg-transparent'); ind.classList.add('bg-[#38bdf8]'); }
      }
      if (typeof renderFreshTeamView === 'function') {
        renderFreshTeamView();
      }
    } else {
      // Default: Always show Team Report
      if (reportContent) reportContent.classList.remove('hidden');
      if (membersContent) membersContent.classList.add('hidden');
      if (headerTitle) headerTitle.textContent = tLang(teamLang, 'দলের রিপোর্ট', 'Team Report', 'تقرير الفريق');

      if (reportTab) {
        reportTab.classList.remove('font-medium', 'text-slate-300');
        reportTab.classList.add('font-bold', 'text-[#38bdf8]');
        const ind = reportTab.querySelector('.team-tab-indicator');
        if (ind) { ind.classList.remove('bg-transparent'); ind.classList.add('bg-[#38bdf8]'); }
      }
      if (membersTab) {
        membersTab.classList.remove('font-bold', 'text-[#38bdf8]');
        membersTab.classList.add('font-medium', 'text-slate-300');
        const ind = membersTab.querySelector('.team-tab-indicator');
        if (ind) { ind.classList.remove('bg-[#38bdf8]'); ind.classList.add('bg-transparent'); }
      }
      if (typeof updateTeamReportMetrics === 'function') {
        updateTeamReportMetrics();
      }
      if (typeof renderFreshTeamView === 'function') {
        renderFreshTeamView();
      }
    }
  }
  forceScrollToTop(nextPanel + '-panel');
  requestAnimationFrame(function() { forceScrollToTop(nextPanel + '-panel'); });
  setTimeout(function() { forceScrollToTop(nextPanel + '-panel'); }, 20);
  setTimeout(function() { forceScrollToTop(nextPanel + '-panel'); }, 60);
  setTimeout(function() { forceScrollToTop(nextPanel + '-panel'); }, 150);

  if (window.aloI18n && typeof window.aloI18n.translateDOM === 'function') {
    setTimeout(function() {
      try { window.aloI18n.translateDOM(); } catch(e) {}
    }, 60);
  }
}

const BDT_PER_USD = 126.0;

function isBangladeshUser(user) {
  if (!user) {
    try {
      user = JSON.parse(localStorage.getItem('aloSignedInUser') || 'null');
    } catch(e) {}
  }
  if (!user) return true;
  if (user.country && String(user.country).trim().toUpperCase() !== 'BD') return false;
  if (user.currency === 'USD' || user.currency === 'INR') return false;
  if (user.dialCode && user.dialCode !== '+880') return false;
  return true;
}
window.isBangladeshUser = isBangladeshUser;

function isUsdOnlyUser(user) {
  return !isBangladeshUser(user);
}
window.isUsdOnlyUser = isUsdOnlyUser;

function isIndianUser(user) {
  return false;
}
window.isIndianUser = isIndianUser;

// Convert a base BDT catalog value to the active user's currency:
// BD -> base BDT unchanged; any non-BD country -> USD using Bangladesh's rate (126 BDT = $1.00 USD)
function toUserCurrencyAmount(baseBdtAmount, user) {
  const num = Number(baseBdtAmount || 0);
  if (!num) return 0;
  if (!user) user = getCurrentUser();
  if (isUsdOnlyUser(user)) {
    return Math.round((num / BDT_PER_USD) * 100) / 100;
  }
  return num;
}
window.toUserCurrencyAmount = toUserCurrencyAmount;

function convertBetweenCurrencies(amount, fromCurrOrUser, toCurrOrUser) {
  const num = Number(amount || 0);
  if (!num) return 0;
  const fromIsUsd = typeof fromCurrOrUser === 'string'
    ? String(fromCurrOrUser).toUpperCase() === 'USD'
    : isUsdOnlyUser(fromCurrOrUser);
  const toIsUsd = typeof toCurrOrUser === 'string'
    ? String(toCurrOrUser).toUpperCase() === 'USD'
    : isUsdOnlyUser(toCurrOrUser);
  if (fromIsUsd === toIsUsd) return num;
  if (fromIsUsd && !toIsUsd) return Number((num * BDT_PER_USD).toFixed(2));
  return Number((num / BDT_PER_USD).toFixed(2));
}
window.convertBetweenCurrencies = convertBetweenCurrencies;

function updateUserDetails(user) {
  if (!user) user = getCurrentUser();
  if (!user) return;

  const isBd = isBangladeshUser(user);
  const countryObj = getCountryByCode(user.country || (isBd ? 'BD' : 'US'));
  user.country = isBd ? 'BD' : countryObj.code;
  user.currency = isBd ? 'BDT' : 'USD';
  user.currencySymbol = isBd ? '৳' : '$';
  user.currencyName = isBd ? 'Taka' : 'USD';
  user.dialCode = isBd ? '+880' : (user.dialCode || countryObj.dialCode || '');
  const isManualLang = Boolean(user.languageManual || localStorage.getItem('alo_lang_manual') === '1');
  user.languageManual = isManualLang;
  user.language = isManualLang
    ? normalizeAppLang((localStorage.getItem('alo_lang_manual') === '1' ? localStorage.getItem('alo_lang') : '') || user.language || (window.aloI18n ? window.aloI18n.getLanguage() : '') || 'en')
    : normalizeAppLang((window.aloI18n ? window.aloI18n.getLanguage() : '') || 'en');

  try {
    localStorage.setItem('aloSignedInUser', JSON.stringify(user));
  } catch(e) {}

  // Sanitize stored user values from any accidental "টি" corruption:
  if (user.accountNumber) user.accountNumber = String(user.accountNumber).replace(/টি/g, '').trim();
  if (user.phone) user.phone = String(user.phone).replace(/টি/g, '').trim();
  if (user.inviteCode) user.inviteCode = String(user.inviteCode).replace(/টি/g, '').trim();
  if (user.memberId) user.memberId = String(user.memberId).replace(/টি/g, '').trim();

  const cleanMemberId = user.memberId || '—';
  const memberId = document.getElementById('profile-member-id');
  if (memberId) memberId.textContent = cleanMemberId;

  const cleanInviteCode = user.inviteCode || '—';
  const inviteCode = document.getElementById('profile-invite-code');
  if (inviteCode) inviteCode.textContent = cleanInviteCode;

  let registeredPhone = String(user.accountNumber || user.phone || '').replace(/টি/g, '').trim();
  const accountNum = document.getElementById('profile-account-number');
  if (accountNum) accountNum.textContent = registeredPhone || '—';

  document.querySelectorAll('[data-profile-value="phone"]').forEach(function(el) {
    el.textContent = registeredPhone;
  });
  document.querySelectorAll('[data-profile-value="account"]').forEach(function(el) {
    el.textContent = registeredPhone;
  });

  const packageLevel = document.getElementById('profile-package-level');
  if (packageLevel) packageLevel.textContent = user.packageLevel || 'LV0';

  if (typeof window.syncCountryLanguageOptions === 'function') {
    window.syncCountryLanguageOptions(user.country || 'BD');
  }
  const currentLang = normalizeAppLang((window.aloI18n ? window.aloI18n.getLanguage() : '') || user.language || localStorage.getItem('alo_lang') || 'en');

  const defaultMemberName = tLang(currentLang, 'সদস্য', 'Member', 'عضو');
  const userName = document.getElementById('dashboard-user-name');
  if (userName) userName.textContent = (!user.name || user.name === 'সদস্য' || user.name === 'Member' || user.name === 'عضو' || user.name === 'सदस्य') ? defaultMemberName : user.name;

  // Country & Currency Information (Bangladesh -> BDT ৳; All other countries -> USD $)
  const userCountryName = currentLang === 'bn'
    ? (isBd ? 'বাংলাদেশ' : (countryObj.nameBn || countryObj.nameEn))
    : (currentLang === 'ar' ? (countryObj.nameAr || countryObj.nameEn) : countryObj.nameEn);
  const userCurrCode = isBd ? 'BDT' : 'USD';
  const userCurrSym = isBd ? '৳' : '$';
  const userFlag = isBd ? '🇧🇩' : (countryObj.flag || '🌍');

  const countryBadge = document.getElementById('profile-country-badge');
  if (countryBadge) {
    countryBadge.innerHTML = `<span class="text-sm select-none">${userFlag}</span> <span>${userCountryName} · ${userCurrCode} (${userCurrSym})</span>`;
  }
  const personalCountry = document.getElementById('personal-country-text');
  if (personalCountry) {
    personalCountry.textContent = `${userFlag} ${userCountryName} (${userCurrCode})`;
  }
  const personalCurrBadge = document.getElementById('personal-currency-badge');
  if (personalCurrBadge) {
    personalCurrBadge.textContent = `${userCurrCode} · ${userCurrSym}`;
  }
  const profileBalCurr = document.getElementById('profile-balance-currency');
  if (profileBalCurr) {
    profileBalCurr.textContent = userCurrCode;
  }

  updatePaymentAndWithdrawalForUser(user);

  if (typeof updateVipHallRooms === 'function') updateVipHallRooms();
  if (typeof updateRecordsPanelPackages === 'function') updateRecordsPanelPackages();
}
window.updateUserDetails = updateUserDetails;

function updatePaymentAndWithdrawalForUser(user) {
  if (!user) user = getCurrentUser();
  const isBd = isBangladeshUser(user);
  const isUsd = !isBd;
  const curr = isBd ? 'BDT' : 'USD';
  const sym = isBd ? '৳' : '$';

  // 1. Payment Method Panel rows (Recharge options)
  document.querySelectorAll('.payment-method-row').forEach(function(row) {
    const method = row.dataset.paymentMethod;
    if (method === 'usdt') {
      row.style.display = '';
    } else {
      // BKASH, Nagad, BKAsh-2 are visible for Bangladesh only!
      row.style.display = isBd ? '' : 'none';
    }
  });

  // 2. Inline Recharge Drawer & Modal Recharge Payment Badges
  document.querySelectorAll('.bd-only-payment-method').forEach(function(badge) {
    badge.style.display = isBd ? '' : 'none';
  });
  const inlineGrid = document.getElementById('inline-recharge-methods-grid');
  if (inlineGrid) {
    inlineGrid.className = isBd ? 'grid grid-cols-3 gap-2 text-center text-[10px]' : 'grid grid-cols-1 gap-2 text-center text-[10px] max-w-[200px] mx-auto';
  }
  const modalGrid = document.getElementById('modal-deposit-methods-grid');
  if (modalGrid) {
    modalGrid.className = isBd ? 'grid grid-cols-3 gap-2 text-center text-[10px]' : 'grid grid-cols-1 gap-2 text-center text-[10px] max-w-[200px] mx-auto';
  }

  // 3. Withdrawal Sheet Method Picker Options
  document.querySelectorAll('.withdraw-picker-option').forEach(function(opt) {
    const key = opt.dataset.methodKey;
    if (key === 'USDT') {
      opt.style.display = '';
    } else {
      // BKASH, NAGAD are visible for Bangladesh only!
      opt.style.display = isBd ? '' : 'none';
    }
  });

  // 4. Withdrawal Label in Sheet
  if (!isBd && (!userSelectedWithdrawMethod || userSelectedWithdrawMethod === 'BKASH' || userSelectedWithdrawMethod === 'NAGAD')) {
    userSelectedWithdrawMethod = 'USDT';
  }
  updateWithdrawalMethodLabelDisplay();
  renderWithdrawMethodPickerOptions();

  // 5. Withdrawal Hint Text (hide BDT withdrawal timeline for non-BD)
  const bdtWithdrawHint = document.querySelector('#my-pass-withdraw-sheet .space-y-1 div:nth-child(2)');
  if (bdtWithdrawHint && (bdtWithdrawHint.textContent.includes('48-96') || bdtWithdrawHint.textContent.includes('উত্তোলন'))) {
    bdtWithdrawHint.style.display = isBd ? '' : 'none';
  }

  // 6. Personal Info Rows (bKash & Nagad hidden for non-BD)
  const personalBkash = document.getElementById('personal-bkash-row');
  if (personalBkash) personalBkash.style.display = isBd ? '' : 'none';
  const personalNagad = document.getElementById('personal-nagad-row');
  if (personalNagad) personalNagad.style.display = isBd ? '' : 'none';

  // 7. Dynamic Currency Text & Symbol Elements
  document.querySelectorAll('.user-currency-text').forEach(function(el) {
    el.textContent = curr;
  });
  document.querySelectorAll('.user-currency-symbol').forEach(function(el) {
    el.textContent = sym;
  });

  // 7b. USDT Exchange Rate Banner Label
  const usdtRateLabel = document.getElementById('usdt-network-rate-label');
  if (usdtRateLabel) {
    const activeRate = Number((window.aloPlatformConfig && window.aloPlatformConfig.usdtRate) || 125);
    usdtRateLabel.textContent = isUsd ? '1 USDT ≈ $1.00 USD' : `1 USDT ≈ ৳${activeRate} BDT`;
  }

  // 8. 9 Earnings Cards Labels in Profile
  const earningsLabelIds = [
    'personal-earnings-value',
    'yesterday-earnings-value',
    'today-earnings-value',
    'weekly-earnings-value',
    'monthly-earnings-value',
    'last-month-earnings-value',
    'total-revenue-value'
  ];
  earningsLabelIds.forEach(function(id) {
    const el = document.getElementById(id);
    if (el && el.nextElementSibling) {
      const currSpan = el.nextElementSibling.querySelector('.user-currency-text');
      if (currSpan) {
        currSpan.textContent = curr;
      } else if (el.nextElementSibling.textContent.includes('(')) {
        el.nextElementSibling.textContent = el.nextElementSibling.textContent.replace(/\([A-Z]{3,4}\)/g, `(${curr})`);
      }
    }
  });

  // 9. Team Report Labels
  document.querySelectorAll('#team-report-panel p, [data-panel="team-report"] p').forEach(function(p) {
    const currSpan = p.querySelector('.user-currency-text');
    if (currSpan) {
      currSpan.textContent = curr;
    } else if (p.textContent.includes('(')) {
      p.textContent = p.textContent.replace(/\([A-Z]{3,4}\)/g, `(${curr})`);
    }
  });

  // 10. VIP Package Cards Currency & Localization
  if (typeof updateRecordsPanelPackages === 'function') {
    updateRecordsPanelPackages();
  }

  // Mission submit reward
  const missionReward = document.getElementById('mission-submit-reward');
  if (missionReward && (missionReward.textContent.includes('BDT') || missionReward.textContent.includes('INR') || missionReward.textContent.includes('PKR') || missionReward.textContent.includes('USD'))) {
    missionReward.textContent = missionReward.textContent.replace(/(BDT|INR|PKR|USD)/g, curr);
  }
}

let _langSaveTimer = null;
window.addEventListener('alo-language-changed', function(e) {
  const lang = normalizeAppLang((e && e.detail && e.detail.lang) || (window.aloI18n && window.aloI18n.getLanguage()) || 'en');
  const user = getCurrentUser();
  if (user) {
    const isUserInit = Boolean(e && e.detail && e.detail.userInitiated);
    user.language = lang;
    if (isUserInit) {
      user.languageManual = true;
    }
    if (!user.profileData || typeof user.profileData !== 'object') user.profileData = {};
    user.profileData.language = lang;
    if (isUserInit) {
      user.profileData.languageManual = true;
    }
    try {
      localStorage.setItem('aloSignedInUser', JSON.stringify(user));
    } catch(err) {}
    updateUserDetails(user);
    if (typeof updateProfileMetrics === 'function') updateProfileMetrics();
    if (typeof updateVipHallRooms === 'function') updateVipHallRooms();
    if (typeof updateRecordsPanelPackages === 'function') updateRecordsPanelPackages();
    if (typeof updateTeamReportMetrics === 'function') updateTeamReportMetrics();
    if (isUserInit && typeof dbSaveUser === 'function') {
      clearTimeout(_langSaveTimer);
      _langSaveTimer = setTimeout(function() {
        dbSaveUser(user).catch(function() {});
      }, 350);
    }
  }
});

async function hashPassword(password) {
  if (window.crypto && window.crypto.subtle && window.TextEncoder) {
    const bytes = new TextEncoder().encode(password);
    const digest = await window.crypto.subtle.digest('SHA-256', bytes);
    return Array.from(new Uint8Array(digest)).map(function(byte) {
      return byte.toString(16).padStart(2, '0');
    }).join('');
  }

  let hash = 2166136261;
  for (let index = 0; index < password.length; index += 1) {
    hash ^= password.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return 'demo-' + (hash >>> 0).toString(16).padStart(8, '0');
}

document.addEventListener('click', function(event) {
  const button = event.target.closest('[data-view]');
  if (button && button.dataset.view) {
    event.preventDefault();
    showView(button.dataset.view);
    return;
  }
});

document.querySelectorAll('[data-view]').forEach(function(button) {
  button.addEventListener('click', function() {
    showView(button.dataset.view);
  });
});

document.querySelectorAll('[data-toggle-password]').forEach(function(button) {
  button.addEventListener('click', function() {
    const field = document.getElementById(button.dataset.togglePassword);
    if (!field) return;
    const showing = field.type === 'password';
    field.type = showing ? 'text' : 'password';
    button.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');
    button.toggleAttribute('data-password-visible', showing);
    const openIcon = button.querySelector('.eye-open-icon');
    const closedIcon = button.querySelector('.eye-closed-icon');
    if (openIcon && closedIcon) {
      openIcon.classList.toggle('hidden', showing);
      closedIcon.classList.toggle('hidden', !showing);
    }
  });
});

document.querySelectorAll('[data-message]').forEach(function(button) {
  button.addEventListener('click', function() {
    const msg = document.getElementById('register-message');
    if (msg) msg.textContent = button.dataset.message;
  });
});

function normalizeBdPhone(phoneStr, countryCode) {
  let digits = String(phoneStr || '').replace(/\D/g, '');
  if (!digits) return '';
  if (countryCode && String(countryCode).toUpperCase() !== 'BD') {
    const country = typeof getCountryByCode === 'function' ? getCountryByCode(countryCode) : null;
    const dialDigits = country && country.dialCode ? country.dialCode.replace(/\D/g, '') : '';
    digits = digits.replace(/^0+/, '');
    if (dialDigits && (!digits.startsWith(dialDigits) || (dialDigits === '1' && digits.length <= 10))) {
      return dialDigits + digits;
    }
    return digits;
  }
  if (countryCode === 'BD') {
    if (digits.startsWith('880')) digits = digits.slice(3);
    if (digits.startsWith('0')) digits = digits.slice(1);
    return digits;
  }
  // When countryCode is omitted: normalize BD numbers, keep international E.164 digits intact
  if (digits.startsWith('880')) {
    digits = digits.slice(3);
    if (digits.startsWith('0')) digits = digits.slice(1);
    return digits;
  }
  if (digits.startsWith('01') && digits.length === 11) {
    return digits.slice(1);
  }
  return digits;
}

