const LEGACY_PACKAGE_NAME_RE = /^(ফ্রি স্তর|বেসিক প্যাকেজ|স্ট্যান্ডার্ড প্যাকেজ|সিলভার প্যাকেজ|গোল্ড প্যাকেজ|প্রিমিয়াম প্যাকেজ|এলিট প্যাকেজ|Free Tier|Basic Package|Standard Package|Silver Package|Gold Package|Premium Package|Elite Package|المستوى المجاني|الباقة الأساسية|الباقة القياسية|الباقة الفضية|الباقة الذهبية|الباقة المميزة|باقة النخبة|(এলিট|Elite|إيليت|एलीट)\s*LV[0-6])$/i;

function getPackageName(level, lang) {
  const l = normalizeAppLang(lang || (window.aloI18n ? window.aloI18n.getLanguage() : 'en'));
  const pkg = packageData[level] || packageData.LV0;
  if (l === 'ar') return pkg.nameAr || pkg.nameEn;
  if (l === 'bn') return pkg.nameBn || pkg.nameEn;
  return pkg.nameEn || pkg.nameBn;
}

const LEVEL_ORDER = ['LV0', 'LV1', 'LV2', 'LV3', 'LV4', 'LV5', 'LV6'];

function applyRemotePackageConfigs(packagesObj, skipCacheWrite) {
  if (!packagesObj || typeof packagesObj !== 'object') return;
  const cachePayload = {};
  let changed = false;

  LEVEL_ORDER.forEach(function(lvl) {
    const src = packagesObj[lvl];
    const targetPkg = packageData[lvl];
    const targetTask = packageTaskSettings[lvl];
    if (!targetPkg || !targetTask) return;

    if (src && typeof src === 'object') {
      const parsedCount = parseInt(src.count, 10);
      const parsedReward = parseFloat(src.reward);
      const parsedPrice = parseFloat(src.price);
      const parsedValidity = parseInt(src.validityDays, 10);

      const nextCount = Number.isFinite(parsedCount) && parsedCount >= 1 ? parsedCount : targetPkg.count;
      const nextReward = Number.isFinite(parsedReward) && parsedReward >= 0 ? parsedReward : targetPkg.reward;
      const nextPrice = Number.isFinite(parsedPrice) && parsedPrice >= 0 ? parsedPrice : targetPkg.price;
      const nextValidity = Number.isFinite(parsedValidity) && parsedValidity >= 1 ? parsedValidity : (targetPkg.validityDays || (lvl === 'LV0' ? 5 : 30));
      const nextDaily = Number((nextCount * nextReward).toFixed(2));
      const rawBn = String(src.nameBn || '').trim();
      const rawEn = String(src.nameEn || '').trim();
      const rawAr = String(src.nameAr || '').trim();
      const nextBn = (rawBn && !LEGACY_PACKAGE_NAME_RE.test(rawBn)) ? rawBn : targetPkg.nameBn;
      const nextEn = (rawEn && !LEGACY_PACKAGE_NAME_RE.test(rawEn)) ? rawEn : targetPkg.nameEn;
      const nextAr = (rawAr && !LEGACY_PACKAGE_NAME_RE.test(rawAr)) ? rawAr : targetPkg.nameAr;

      if (
        targetPkg.count !== nextCount ||
        targetPkg.reward !== nextReward ||
        targetPkg.price !== nextPrice ||
        targetPkg.validityDays !== nextValidity ||
        targetPkg.nameBn !== nextBn ||
        targetPkg.nameEn !== nextEn ||
        targetPkg.nameAr !== nextAr
      ) {
        changed = true;
      }

      targetTask.count = nextCount;
      targetTask.reward = nextReward;

      targetPkg.count = nextCount;
      targetPkg.reward = nextReward;
      targetPkg.price = nextPrice;
      targetPkg.validityDays = nextValidity;
      targetPkg.dailyIncome = nextDaily;
      targetPkg.nameBn = nextBn;
      targetPkg.nameEn = nextEn;
      targetPkg.nameAr = nextAr;
      targetPkg.name = nextEn;
      targetPkg.desc = `দৈনিক ${nextCount}টি কাজ · প্রতি কাজের আয় ${nextReward}`;
    }

    cachePayload[lvl] = {
      count: targetPkg.count,
      reward: targetPkg.reward,
      price: targetPkg.price,
      validityDays: targetPkg.validityDays || (lvl === 'LV0' ? 5 : 30),
      nameBn: targetPkg.nameBn,
      nameEn: targetPkg.nameEn,
      nameAr: targetPkg.nameAr
    };
  });

  if (!skipCacheWrite) {
    try {
      localStorage.setItem('alo_system_packages_cache', JSON.stringify(cachePayload));
    } catch (e) {}
  }

  if (changed) {
    if (typeof updateVipHallRooms === 'function') updateVipHallRooms();
    if (typeof updateRecordsPanelPackages === 'function') updateRecordsPanelPackages();
    if (typeof updateProfileMetrics === 'function') updateProfileMetrics();
    const taskPanel = document.getElementById('platform-tasks-panel');
    if (taskPanel && !taskPanel.hidden && typeof renderPackageTasks === 'function') {
      renderPackageTasks(activePackageLevel || 'LV0');
    }
    const detailPanel = document.getElementById('package-detail-panel');
    if (detailPanel && !detailPanel.hidden && typeof renderPackageDetailPage === 'function') {
      renderPackageDetailPage(activeDetailPackageLevel || 'LV1');
    }
  }
}
window.applyRemotePackageConfigs = applyRemotePackageConfigs;

try {
  const cachedPkgRaw = localStorage.getItem('alo_system_packages_cache');
  if (cachedPkgRaw) {
    const cachedPkgObj = JSON.parse(cachedPkgRaw);
    if (cachedPkgObj && typeof cachedPkgObj === 'object') {
      applyRemotePackageConfigs(cachedPkgObj, false);
    }
  }
} catch (e) {}

function getCurrentUser() {
  let user = null;
  try {
    user = JSON.parse(localStorage.getItem('aloSignedInUser') || 'null');
  } catch (e) {
    user = null;
  }

  if (!user || (!user.phone && !user.accountNumber)) {
    return null;
  }

  if (!user.accountNumber && user.phone) {
    user.accountNumber = user.phone;
  } else if (!user.phone && user.accountNumber) {
    user.phone = user.accountNumber;
  }

  // Strictly enforce currency based on country (BD -> BDT, non-BD -> USD),
  // while always preserving user's chosen/registered UI language (default 'en')!
  const isBd = isBangladeshUser(user);
  const isManualLang = Boolean(user.languageManual || localStorage.getItem('alo_lang_manual') === '1');
  user.languageManual = isManualLang;
  user.language = isManualLang
    ? normalizeAppLang(user.language || localStorage.getItem('alo_lang') || 'en')
    : 'en';
  if (!isBd) {
    const cObj = getCountryByCode(user.country || 'US');
    user.country = cObj.code === 'BD' ? 'US' : cObj.code;
    user.currency = 'USD';
    user.currencySymbol = '$';
    user.currencyName = 'USD';
    user.dialCode = user.dialCode || cObj.dialCode || '';
    user.countryName = cObj.nameEn;
  } else {
    user.country = 'BD';
    user.currency = 'BDT';
    user.currencySymbol = '৳';
    user.currencyName = 'Taka';
    user.dialCode = '+880';
  }
  if (!user.name || user.name === 'সদস্য' || user.name === 'Member' || user.name === 'عضو' || user.name === 'सदस्य') {
    user.name = tLang(user.language, 'সদস্য', 'Member', 'عضو');
  }

  if (user.accountNumber) user.accountNumber = String(user.accountNumber).replace(/টি/g, '').trim();
  if (user.phone) user.phone = String(user.phone).replace(/টি/g, '').trim();
  if (user.inviteCode) user.inviteCode = String(user.inviteCode).replace(/টি/g, '').trim();
  if (user.memberId) user.memberId = String(user.memberId).replace(/টি/g, '').trim();

  return user;
}

function formatBanglaNumber(num) {
  const banglaDigits = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];
  return String(num).replace(/[0-9]/g, function(d) {
    return banglaDigits[parseInt(d, 10)];
  });
}

function formatMoney(amount, user) {
  if (!user) user = getCurrentUser();
  const lang = getActiveLang(user);
  const num = Number(amount || 0);
  const formatted = num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (lang === 'bn') {
    return formatBanglaNumber(formatted);
  }
  return formatted;
}

function formatNumber(num, user) {
  if (!user) user = getCurrentUser();
  const lang = getActiveLang(user);
  const n = Number(num || 0);
  const formatted = n.toLocaleString('en-US');
  if (lang === 'bn') {
    return formatBanglaNumber(formatted);
  }
  return formatted;
}

function getActiveLang(user) {
  if (!user) user = getCurrentUser();
  return normalizeAppLang((window.aloI18n ? window.aloI18n.getLanguage() : '') || (user && user.language) || localStorage.getItem('alo_lang') || 'en');
}

function getVipTierLabel(tierKey, lang) {
  const l = normalizeAppLang(lang || getActiveLang());
  if (l === 'bn') return tierKey;
  const bnToNum = { '১': 1, '২': 2, '৩': 3, '৪': 4, '৫': 5, '৬': 6, '৭': 7, '৮': 8 };
  const m = String(tierKey || '').match(/([১-৮\d]+)/);
  const num = m ? (bnToNum[m[1]] || m[1]) : tierKey;
  return l === 'ar' ? ('المركز ' + num) : ('Position ' + num);
}

function getLv0TrialStatus(user) {
  if (!user) user = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
  const lvl = String((user && user.packageLevel) || 'LV0').toUpperCase().trim();
  const hasPaidPkg = lvl !== 'LV0' || (user && Array.isArray(user.purchasedPackages) && user.purchasedPackages.some(function(p) {
    const up = String(p || '').toUpperCase().trim();
    return Boolean(up && up !== 'LV0' && /^LV[1-9]\d*$/.test(up));
  }));
  const validityDays = Math.max(1, parseInt((packageData.LV0 && packageData.LV0.validityDays) || 5, 10) || 5);
  if (!user) {
    return { isLv0Only: false, isExpired: false, validityDays: validityDays, daysLeft: validityDays };
  }
  const createdTs = new Date(user.createdAt || user.created_at || Date.now()).getTime();
  if (!Number.isFinite(createdTs) || createdTs <= 0) {
    return { isLv0Only: !hasPaidPkg, isExpired: false, validityDays: validityDays, daysLeft: validityDays };
  }
  const totalMs = validityDays * 24 * 60 * 60 * 1000;
  const elapsedMs = Math.max(0, Date.now() - createdTs);
  const remainingMs = totalMs - elapsedMs;
  const isExpired = remainingMs <= 0;
  const daysLeft = isExpired ? 0 : Math.max(1, Math.ceil(remainingMs / (24 * 60 * 60 * 1000)));
  return {
    isLv0Only: !hasPaidPkg,
    isExpired: isExpired,
    validityDays: validityDays,
    daysLeft: daysLeft
  };
}
window.getLv0TrialStatus = getLv0TrialStatus;

function isLevelUnlocked(targetLevel, user) {
  if (!user) user = getCurrentUser();
  if (targetLevel === 'LV0') {
    const trialStatus = getLv0TrialStatus(user);
    return !trialStatus.isExpired;
  }
  if (!user) return false;
  if (user.purchasedPackages && user.purchasedPackages.includes(targetLevel)) {
    return true;
  }
  const userLevel = user.packageLevel || 'LV0';
  const userIdx = LEVEL_ORDER.indexOf(userLevel);
  const targetIdx = LEVEL_ORDER.indexOf(targetLevel);
  return userIdx >= targetIdx && userIdx > 0;
}

let currentPurchaseLevel = 'LV1';
let pendingPurchaseLevel = '';
let selectedDepositAmount = 3500;

function syncLv0ExpiredStamp(cardEl, shouldShow) {
  if (!cardEl) return;
  const existing = cardEl.querySelector('.lv0-expired-stamp-overlay');
  if (shouldShow) {
    if (!existing) {
      const overlay = document.createElement('div');
      overlay.className = 'lv0-expired-stamp-overlay';
      overlay.setAttribute('aria-hidden', 'true');
      const img = document.createElement('img');
      img.src = '/assets/aistudio/images__1__b17277ca.jpeg';
      img.alt = 'EXPIRED';
      img.className = 'lv0-expired-stamp-img';
      img.draggable = false;
      overlay.appendChild(img);
      cardEl.appendChild(overlay);
    }
  } else if (existing) {
    existing.remove();
  }
}

function updateVipHallRooms() {
  const user = getCurrentUser();
  const userLevel = (user && user.packageLevel) || 'LV0';
  const lv0Status = getLv0TrialStatus(user);
  const rooms = document.querySelectorAll('.hall-level-room');
  rooms.forEach(function(room) {
    const lvl = room.dataset.level;
    if (!lvl) return;
    const isCurrent = (lvl === userLevel);
    const isLv0ExpiredHere = (lvl === 'LV0' && lv0Status.isExpired);

    const lang = getActiveLang(user);
    const hallLabels = {
      current: tLang(lang, 'বর্তমান স্তর', 'Current Tier', 'المستوى الحالي'),
      dailyWork: tLang(lang, 'দৈনন্দিন কর্ম:', 'Daily Tasks:', 'المهام اليومية:')
    };

    const pkg = packageData[lvl];
    const titleP = room.querySelector('p:not(.hall-daily-work)');
    if (titleP) {
      titleP.textContent = getPackageName(lvl, lang) || lvl;
    }
    const workP = room.querySelector('.hall-daily-work') || room.querySelector('p:last-of-type');
    if (workP && pkg) {
      workP.innerHTML = `${hallLabels.dailyWork} <strong class="ml-0.5 font-normal">${pkg.count}</strong>`;
    }

    let tag = room.querySelector('.hall-current-tag, .hall-status-tag');
    if (isCurrent && !isLv0ExpiredHere) {
      if (!tag) {
        tag = document.createElement('span');
        room.insertBefore(tag, room.firstChild);
      }
      tag.className = 'hall-current-tag';
      tag.textContent = hallLabels.current;
      tag.style.background = '';
      tag.style.color = '';
    } else if (tag) {
      tag.remove();
    }

    syncLv0ExpiredStamp(room, isLv0ExpiredHere);
  });
}

function formatValidityLabel(days, lang) {
  const d = Math.max(1, parseInt(days, 10) || 1);
  if (lang === 'bn') {
    return `মেয়াদ: ${formatBanglaNumber(d)} দিন`;
  }
  if (lang === 'ar') {
    return `الصلاحية: ${d} ${d >= 3 && d <= 10 ? 'أيام' : 'يوماً'}`;
  }
  return `Validity: ${d} ${d === 1 ? 'Day' : 'Days'}`;
}

function updateRecordsPanelPackages() {
  const user = getCurrentUser();
  const isUsd = isUsdOnlyUser(user);
  const userLevel = (user && user.packageLevel) || 'LV0';
  const curr = getUserCurrency(user);
  const sym = getUserCurrencySymbol(user);
  const lang = getActiveLang(user);

  const curLevelDisplay = document.getElementById('records-current-level-display');
  if (curLevelDisplay) {
    const pkgName = getPackageName(userLevel, lang);
    curLevelDisplay.textContent = pkgName || userLevel;
  }
  if (typeof reconcileUserFrozenBuckets === 'function' && user) {
    reconcileUserFrozenBuckets(user);
  }
  const balDisplay = document.getElementById('records-balance-display');
  if (balDisplay) {
    const pkgSpendableBal = Number((Number((user && user.balance) || 0) + Number((user && user.rechargeFrozenBalance) || 0)).toFixed(2));
    balDisplay.textContent = formatMoney(pkgSpendableBal, user);
  }

  const labels = {
    dailyTasks: tLang(lang, 'দৈনিক কাজ:', 'Daily Tasks:', 'المهام اليومية:'),
    perTask: tLang(lang, 'প্রতি কাজ:', 'Per Task:', 'لكل مهمة:'),
    dailyIncome: tLang(lang, 'দৈনিক আয়:', 'Daily Income:', 'الدخل اليومي:'),
    btnCurrent: tLang(lang, 'বর্তমান স্তর', 'Current Tier', 'المستوى الحالي'),
    btnPurchased: tLang(lang, 'ক্রয় করা হয়েছে ✓', 'Purchased ✓', 'تم الشراء ✓'),
    btnBuy: tLang(lang, 'প্যাকেজ ক্রয় করুন', 'Buy Package', 'شراء الباقة'),
    freeText: tLang(lang, 'ফ্রি', 'Free', 'مجاني'),
    tasksUnit: lang === 'bn' ? 'টি' : ''
  };

  const lv0Trial = getLv0TrialStatus(user);
  const pkgCards = document.querySelectorAll('[data-record-package]');
  pkgCards.forEach(function(card) {
    const level = card.dataset.recordPackage;
    const pkg = packageData[level];
    if (!pkg) return;
    const pkgName = getPackageName(level, lang);
    const pkgPrice = toUserCurrencyAmount(pkg.price, user);
    const pkgReward = toUserCurrencyAmount(pkg.reward, user);
    const pkgDaily = isUsd ? Number((pkgReward * pkg.count).toFixed(2)) : pkg.dailyIncome;
    const validityDays = Math.max(1, parseInt(pkg.validityDays, 10) || (level === 'LV0' ? 5 : 30));
    const isLv0ExpiredCard = (level === 'LV0' && lv0Trial.isExpired);

    // 1. Update Validity Badge text (live synced from Admin Panel)
    const validityBadgeEl = card.querySelector('.package-validity-badge');
    const validityTextEl = card.querySelector('.package-validity-badge .package-validity-text, .package-validity-badge span:last-child');
    if (validityTextEl) {
      validityTextEl.textContent = formatValidityLabel(validityDays, lang);
    }
    if (validityBadgeEl && level === 'LV0') {
      validityBadgeEl.className = 'package-validity-badge inline-flex items-center gap-1 px-2.5 py-0.5 rounded-md text-[10.5px] font-semibold bg-sky-500/20 text-[#38bdf8] select-none';
    }

    // 1b. Update Package Label per active language (LV0 - LV6)
    const levelTitleP = card.querySelector('p.text-xs.font-semibold');
    if (levelTitleP) {
      levelTitleP.textContent = pkgName || level;
    }

    // 2. Update Price
    const priceEl = card.querySelector('h3');
    if (priceEl) {
      if (pkg.price === 0) {
        priceEl.textContent = isUsd ? `$0.00 ${curr} (${labels.freeText})` : `${formatNumber(0, user)} ${curr} (${labels.freeText})`;
      } else {
        priceEl.textContent = isUsd ? `${sym}${formatMoney(pkgPrice, user)} ${curr}` : `${formatNumber(pkgPrice, user)} ${curr}`;
      }
    }

    // 3. Update Metrics Grid
    const metricSpans = card.querySelectorAll('.text-slate-400, .text-slate-300');
    if (metricSpans.length >= 3) {
      metricSpans[0].textContent = labels.dailyTasks;
      metricSpans[1].textContent = labels.perTask;
      metricSpans[2].textContent = labels.dailyIncome;
    }
    const metricValues = card.querySelectorAll('strong');
    if (metricValues.length >= 3) {
      metricValues[0].textContent = `${formatNumber(pkg.count, user)}${labels.tasksUnit}`;
      metricValues[1].textContent = isUsd ? `${sym}${formatMoney(pkgReward, user)} ${curr}` : `${formatMoney(pkgReward, user)} ${curr}`;
      metricValues[2].textContent = isUsd ? `${sym}${formatMoney(pkgDaily, user)} ${curr}` : `${formatMoney(pkgDaily, user)} ${curr}`;
    }

    // 4. Update Button
    const btn = card.querySelector('[data-buy-package]');
    if (btn) {
      const isCurrent = (level === userLevel);
      const isPurchased = (user && user.purchasedPackages && user.purchasedPackages.includes(level));

      if (isCurrent) {
        btn.textContent = labels.btnCurrent;
        btn.disabled = true;
        btn.className = 'package-card-btn rounded-[var(--radius-round)] px-3 py-1.5 text-xs font-bold shadow bg-slate-700/60 text-slate-300 cursor-default';
      } else if (isPurchased) {
        btn.textContent = labels.btnPurchased;
        btn.disabled = true;
        btn.className = 'package-card-btn rounded-[var(--radius-round)] px-3 py-1.5 text-xs font-bold shadow bg-emerald-700/60 text-emerald-200 cursor-default';
      } else {
        btn.textContent = labels.btnBuy;
        btn.disabled = false;
        btn.className = 'package-card-btn rounded-[var(--radius-round)] px-3 py-1.5 text-xs font-bold shadow bg-[#1877f2] hover:bg-[#166fe5] text-white active:scale-95 cursor-pointer';
      }
    }

    // 5. Overlay clean EXPIRED stamp image when 5-day free validity has ended
    syncLv0ExpiredStamp(card, isLv0ExpiredCard);
  });
}

function switchSheetTab(tabName) {
  const purchaseTabBtn = document.getElementById('sheet-tab-purchase');
  const depositTabBtn = document.getElementById('sheet-tab-deposit');
  const purchaseView = document.getElementById('sheet-purchase-view');
  const depositView = document.getElementById('sheet-deposit-view');

  if (tabName === 'deposit') {
    if (depositTabBtn) {
      depositTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 bg-[#10b981] text-white shadow font-bold cursor-pointer';
    }
    if (purchaseTabBtn) {
      purchaseTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 text-slate-400 hover:text-white font-bold cursor-pointer';
    }
    if (depositView) depositView.classList.remove('hidden');
    if (purchaseView) purchaseView.classList.add('hidden');
  } else {
    if (purchaseTabBtn) {
      purchaseTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 bg-[#1264c9] text-white shadow font-bold cursor-pointer';
    }
    if (depositTabBtn) {
      depositTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 text-slate-400 hover:text-white font-bold cursor-pointer';
    }
    if (purchaseView) purchaseView.classList.remove('hidden');
    if (depositView) depositView.classList.add('hidden');
  }
}

function openActionSheet() {
  const backdrop = document.getElementById('alo-action-backdrop');
  const sheet = document.getElementById('alo-action-sheet');
  if (backdrop) {
    backdrop.classList.add('is-active');
    backdrop.style.display = 'block';
  }
  if (sheet) {
    sheet.classList.add('is-active');
    sheet.style.display = 'flex';
  }
}

function closeActionSheet() {
  const backdrop = document.getElementById('alo-action-backdrop');
  const sheet = document.getElementById('alo-action-sheet');
  if (backdrop) {
    backdrop.classList.remove('is-active');
    setTimeout(function() {
      if (!backdrop.classList.contains('is-active')) {
        backdrop.style.display = 'none';
      }
    }, 320);
  }
  if (sheet) {
    sheet.classList.remove('is-active');
    setTimeout(function() {
      if (!sheet.classList.contains('is-active')) {
        sheet.style.display = 'none';
      }
    }, 380);
  }
}

document.addEventListener('keydown', function(event) {
  if (event.key === 'Escape') {
    closeActionSheet();
    closeManagerContactModal();
    closeCountryPickerModal();
    closePackageDetailsModal();
    if (typeof closeTeamMemberDetailModal === 'function') {
      closeTeamMemberDetailModal();
    }
  }
});

function openManagerContactModal() {
  openDashboardPanel('customer-service');
}

function closeManagerContactModal() {
  const modal = document.getElementById('manager-contact-modal');
  if (modal) {
    modal.hidden = true;
    modal.style.display = 'none';
  }
}
window.openManagerContactModal = openManagerContactModal;
window.closeManagerContactModal = closeManagerContactModal;

