function copyTextHelper(text, onSuccess) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(function() {
      if (typeof onSuccess === 'function') onSuccess();
    }).catch(function() {
      fallbackExecCopy(text, onSuccess);
    });
  } else {
    fallbackExecCopy(text, onSuccess);
  }
}

function fallbackExecCopy(text, onSuccess) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    if (typeof onSuccess === 'function') onSuccess();
  } catch (e) {}
}

function initUsdtDeposit() {
  // 1. Copy Unique BEP20 Address
  const copyBtn = document.getElementById('copy-company-usdt-address-btn');
  const copyBtnText = document.getElementById('copy-btn-text');
  if (copyBtn) {
    copyBtn.onclick = function(e) {
      e.preventDefault();
      const targetAddress = currentUserBep20Address || COMPANY_USDT_BEP20_ADDRESS;
      copyTextHelper(targetAddress, function() {
        if (copyBtnText) copyBtnText.textContent = '✓ Copied!';
        if (typeof showToastNotification === 'function') {
          showToastNotification('BEP20 Address Copied!');
        }
        setTimeout(function() {
          if (copyBtnText) copyBtnText.textContent = 'Copy Address';
        }, 2500);
      });
    };
  }

  // Preload unique address
  if (typeof loadUserCryptoDepositAddress === 'function') {
    loadUserCryptoDepositAddress();
  }

  // 2. Paste TxHash from Clipboard
  const pasteBtn = document.getElementById('usdt-paste-tx-btn');
  const txInput = document.getElementById('usdt-txhash-input');
  if (pasteBtn && txInput) {
    pasteBtn.onclick = async function(e) {
      e.preventDefault();
      try {
        if (navigator.clipboard && navigator.clipboard.readText) {
          const text = await navigator.clipboard.readText();
          if (text) {
            txInput.value = text.trim();
            if (typeof showToastNotification === 'function') {
              const l = getActiveLang();
              showToastNotification(tLang(l, 'TxHash পেস্ট করা হয়েছে', 'TxHash pasted', 'تم لصق TxHash'));
            }
          }
        } else {
          txInput.focus();
        }
      } catch (err) {
        txInput.focus();
      }
    };
  }

  // 3. Amount Input -> User currency preview calculation
  const amountInput = document.getElementById('usdt-amount-input');
  const bdtPreview = document.getElementById('usdt-bdt-preview');
  if (amountInput && bdtPreview) {
    amountInput.oninput = function() {
      const val = parseFloat(amountInput.value) || 0;
      const u = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
      const activeRate = isUsdOnlyUser(u) ? 1 : Number((window.aloPlatformConfig && window.aloPlatformConfig.usdtRate) || 125);
      bdtPreview.textContent = (val * activeRate).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };
  }

  // 4. Back Button
  const backBtn = document.getElementById('usdt-deposit-back-btn');
  if (backBtn) {
    backBtn.onclick = function(e) {
      e.preventDefault();
      const detailsCard = document.getElementById('usdt-deposit-details-card');
      const preView = document.getElementById('usdt-pre-deposit-view');
      if (detailsCard && !detailsCard.classList.contains('hidden')) {
        showUsdtSelectionView();
        return;
      }
      openDashboardPanel('payment-method');
    };
  }

  // 5. Submit & Auto-Approve Button
  const submitBtn = document.getElementById('usdt-submit-deposit-btn');
  const msgEl = document.getElementById('usdt-submit-message');
  const senderInput = document.getElementById('usdt-sender-address-input');
  const btnSpinner = document.getElementById('usdt-btn-spinner');
  const btnIcon = document.getElementById('usdt-btn-icon');
  const btnText = document.getElementById('usdt-btn-text');

  if (submitBtn) {
    submitBtn.onclick = async function(e) {
      e.preventDefault();
      const user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
      const l = getActiveLang(user);
      if (!user) {
        if (typeof showToastNotification === 'function') {
          showToastNotification(tLang(l, 'অনুগ্রহ করে প্রথমে লগইন করুন', 'Please log in first.', 'يرجى تسجيل الدخول أولاً.'));
        }
        return;
      }

      const txHash = txInput ? txInput.value.trim() : '';
      const senderAddress = senderInput ? senderInput.value.trim() : '';

      if (!senderAddress) {
        if (msgEl) {
          msgEl.className = 'text-xs text-center font-semibold text-rose-400 py-1.5 bg-rose-500/10 rounded-lg border border-rose-500/30';
          msgEl.textContent = tLang(l, 'অনুগ্রহ করে আপনার প্রেরক ওয়ালেট অ্যাড্রেস (Sender Address) প্রদান করুন।', 'Please provide your sender wallet address.', 'يرجى إدخال عنوان محفظة المرسل.');
          msgEl.classList.remove('hidden');
        }
        if (senderInput) senderInput.focus();
        return;
      }

      if (!/^0x[a-fA-F0-9]{40}$/.test(senderAddress)) {
        if (msgEl) {
          msgEl.className = 'text-xs text-center font-semibold text-rose-400 py-1.5 bg-rose-500/10 rounded-lg border border-rose-500/30';
          msgEl.textContent = tLang(l, 'ভুল প্রেরক ওয়ালেট অ্যাড্রেস ফরম্যাট (0x দিয়ে শুরু হওয়া ৪২ অক্ষরের হতে হবে)।', 'Invalid sender address format (must start with 0x and be 42 chars).', 'صيغة عنوان المرسل غير صحيحة (يجب أن يبدأ بـ 0x ويتكون من 42 حرفاً).');
          msgEl.classList.remove('hidden');
        }
        if (senderInput) senderInput.focus();
        return;
      }

      if (!txHash) {
        if (msgEl) {
          msgEl.className = 'text-xs text-center font-semibold text-rose-400 py-1.5 bg-rose-500/10 rounded-lg border border-rose-500/30';
          msgEl.textContent = tLang(l, 'অনুগ্রহ করে ট্রানজেকশন হ্যাশ (TxHash / TxID) প্রদান করুন।', 'Please provide the transaction hash (TxHash / TxID).', 'يرجى إدخال معرّف المعاملة (TxHash / TxID).');
          msgEl.classList.remove('hidden');
        }
        if (txInput) txInput.focus();
        return;
      }

      if (!/^0x[a-fA-F0-9]{64}$/.test(txHash)) {
        if (msgEl) {
          msgEl.className = 'text-xs text-center font-semibold text-rose-400 py-1.5 bg-rose-500/10 rounded-lg border border-rose-500/30';
          msgEl.textContent = tLang(l, 'ভুল TxHash ফরম্যাট! ট্রানজেকশন হ্যাশ অবশ্যই 0x দিয়ে শুরু হওয়া ৬৬ অক্ষরের হেক্সাডেসিমাল কোড হতে হবে।', 'Invalid TxHash format! Must start with 0x and be a 66-char hex hash.', 'صيغة TxHash غير صحيحة! يجب أن يبدأ بـ 0x ويتكون من 66 حرفاً ست عشرياً.');
          msgEl.classList.remove('hidden');
        }
        return;
      }

      // Enter loading state
      submitBtn.disabled = true;
      if (btnSpinner) btnSpinner.classList.remove('hidden');
      if (btnIcon) btnIcon.classList.add('hidden');
      if (btnText) btnText.textContent = tLang(l, 'ব্লকচেইন ভেরিফাই হচ্ছে...', 'Verifying on blockchain...', 'جاري التحقق عبر البلوكتشين...');
      if (msgEl) {
        msgEl.className = 'text-xs text-center font-semibold text-sky-400 py-1.5 bg-sky-500/10 rounded-lg border border-sky-500/30 animate-pulse';
        msgEl.textContent = tLang(l, 'অন-চেইন রিসিপ্ট ও ১৫ কনফার্মেশন যাচাই করা হচ্ছে...', 'Checking on-chain receipt and confirmations...', 'جاري فحص إيصال الشبكة وتأكيدات البلوكتشين...');
        msgEl.classList.remove('hidden');
      }

      try {
        const payload = {
          txHash: txHash,
          senderAddress: senderAddress
        };

        const result = await submitDeposit(payload);

        if (result && result.success) {
          const depositData = result.deposit || {};
          const usdtAmount = Number(depositData.usdtAmount) || 0;
          const isUsd = isUsdOnlyUser(user);
          const creditAmount = isUsd ? Number(usdtAmount.toFixed(2)) : (Number(depositData.bdtAmount) || 0);

          // 1. Credit Recharged Funds to Frozen Balance (withdrawals require LV1+ task earnings)
          user.frozenBalance = Number(((Number(user.frozenBalance) || 0) + creditAmount).toFixed(2));
          user.rechargeFrozenBalance = Number(((Number(user.rechargeFrozenBalance) || 0) + creditAmount).toFixed(2));
          user.rechargeAmount = Number(((Number(user.rechargeAmount) || 0) + creditAmount).toFixed(2));

          localStorage.setItem('aloSignedInUser', JSON.stringify(user));
          if (typeof dbSaveUser === 'function') {
            dbSaveUser(user);
          }

          // 2. Record / Upgrade Transaction
          const manualUsdtOrderId = depositData.txHash || txHash;
          const nowManual = new Date();
          const dateStr = nowManual.toISOString().split('T')[0];
          const timeStr = nowManual.toTimeString().split(' ')[0];
          const uPhoneManual = user.phone || user.accountNumber;
          let upgradedPendingUsdt = false;

          if (window.aloSupabase && uPhoneManual) {
            try {
              const normP = normalizeBdPhone(uPhoneManual);
              const { data: pendingRows } = await window.aloSupabase
                .from('transactions')
                .select('id, method, created_at, status')
                .eq('phone', normP)
                .eq('type', 'deposit')
                .ilike('method', '%USDT%')
                .order('created_at', { ascending: false })
                .limit(5);
              const activePen = (Array.isArray(pendingRows) ? pendingRows : []).find(function(r) {
                const stL = String(r.status || '').toLowerCase();
                const isPen = !stL.includes('অনুমোদিত') && !stL.includes('অসফল') && !stL.includes('fail') && !stL.includes('approv') && !stL.includes('বাতিল');
                const ageMs = Date.now() - Date.parse(r.created_at || '');
                return isPen && (isNaN(ageMs) || ageMs < 10 * 60 * 1000);
              });
              if (activePen) {
                await window.aloSupabase
                  .from('transactions')
                  .update({
                    amount: creditAmount,
                    actual: creditAmount,
                    ratio: '100%',
                    status: 'অনুমোদিত',
                    method: formatMethodWithOrderId('USDT (BEP20)', manualUsdtOrderId)
                  })
                  .eq('id', activePen.id);
                upgradedPendingUsdt = true;
                if (typeof upsertLocalDepositOrder === 'function') {
                  upsertLocalDepositOrder(normP, {
                    id: activePen.id,
                    orderId: extractOrderIdFromTx(activePen) || manualUsdtOrderId,
                    type: 'deposit',
                    amount: creditAmount,
                    actual: creditAmount,
                    ratio: '100%',
                    status: 'অনুমোদিত',
                    method: 'USDT (BEP20)',
                    createdAt: activePen.created_at || nowManual.toISOString()
                  });
                }
              }
            } catch (eManualUp) {}
          }

          if (!upgradedPendingUsdt) {
            if (typeof upsertLocalDepositOrder === 'function') {
              upsertLocalDepositOrder(uPhoneManual, {
                orderId: manualUsdtOrderId,
                type: 'deposit',
                amount: creditAmount,
                actual: creditAmount,
                ratio: '100%',
                status: 'অনুমোদিত',
                method: 'USDT (BEP20)',
                date: dateStr,
                time: timeStr,
                createdAt: nowManual.toISOString()
              });
            }
            if (typeof dbRecordTransaction === 'function') {
              dbRecordTransaction({
                phone: uPhoneManual,
                type: 'deposit',
                amount: creditAmount,
                actual: creditAmount,
                ratio: '100%',
                status: 'অনুমোদিত',
                method: 'USDT (BEP20)',
                order_id: manualUsdtOrderId,
                date: dateStr,
                time: timeStr,
                newBalance: Number(user.balance) || 0
              });
            }
          }

          // 3. Update UI
          if (typeof updateUserDetails === 'function') updateUserDetails(user);
          if (typeof updateProfileMetrics === 'function') updateProfileMetrics();
          if (typeof updateRecordsPanelPackages === 'function') updateRecordsPanelPackages();
          if (typeof updateVipHallRooms === 'function') updateVipHallRooms();
          if (typeof updatePaymentAndWithdrawalForUser === 'function') updatePaymentAndWithdrawalForUser();

          // 4. Record Locally & Re-render
          saveLocalUsdtDepositRecord({
            txHash: manualUsdtOrderId,
            senderAddress: depositData.senderAddress || senderAddress,
            usdtAmount: usdtAmount,
            bdtAmount: creditAmount
          });
          renderRecentUsdtDeposits();
          if (typeof renderAccountChangeHistory === 'function') renderAccountChangeHistory();

          // 5. Success Feedback
          if (msgEl) {
            msgEl.className = 'text-xs text-center font-bold text-emerald-400 py-2 px-3 bg-emerald-500/15 rounded-xl border border-emerald-500/40';
            msgEl.textContent = isUsd
              ? tLang(
                  l,
                  `🎉 সফল! ${usdtAmount} USDT ($${creditAmount.toFixed(2)} USD) অটো এপ্রুভ হয়েছে।`,
                  `🎉 Success! ${usdtAmount} USDT ($${creditAmount.toFixed(2)} USD) auto-approved & credited.`,
                  `🎉 تم بنجاح! تمت الموافقة التلقائية وإضافة ${usdtAmount} USDT ($${creditAmount.toFixed(2)} USD).`
                )
              : tLang(
                  l,
                  (result.message || `🎉 অভিনন্দন! ${usdtAmount} USDT (৳ ${creditAmount.toLocaleString('en-US')}) অটো এপ্রুভ হয়েছে।`),
                  `🎉 Success! ${usdtAmount} USDT (৳ ${creditAmount.toLocaleString('en-US')}) auto-approved & credited.`,
                  `🎉 تم بنجاح! تمت الموافقة وإضافة ${usdtAmount} USDT (৳ ${creditAmount.toLocaleString('en-US')}).`
                );
            msgEl.classList.remove('hidden');
          }

          if (typeof showToastNotification === 'function') {
            showToastNotification(
              isUsd
                ? tLang(
                    l,
                    `🎉 ${usdtAmount} USDT আপনার USD ব্যালেন্সে যুক্ত হয়েছে!`,
                    `🎉 ${usdtAmount} USDT deposit credited to your USD balance!`,
                    `🎉 تمت إضافة إيداع ${usdtAmount} USDT إلى رصيدك!`
                  )
                : tLang(
                    l,
                    `🎉 ${usdtAmount} USDT ডিপোজিট সফল ও ব্যালেন্সে যুক্ত হয়েছে!`,
                    `🎉 ${usdtAmount} USDT deposit credited to your balance!`,
                    `🎉 تم إيداع ${usdtAmount} USDT وإضافته إلى رصيدك بنجاح!`
                  )
            );
          }

          // Clear inputs
          if (txInput) txInput.value = '';
          if (senderInput) senderInput.value = '';
          if (amountInput) amountInput.value = '';
          if (bdtPreview) bdtPreview.textContent = (isUsd || l !== 'bn') ? '0.00' : '০.০০';

        } else {
          // Failure response from API
          const errMsg = (l !== 'bn' && result && result.messageEn)
            ? result.messageEn
            : ((result && result.message)
              ? result.message
              : tLang(l, 'ডিপোজিট ভেরিফিকেশন ব্যর্থ হয়েছে।', 'Deposit verification failed.', 'فشل التحقق من الإيداع.'));
          if (msgEl) {
            msgEl.className = 'text-xs text-center font-semibold text-rose-400 py-2 px-3 bg-rose-500/15 rounded-xl border border-rose-500/40';
            msgEl.textContent = errMsg;
            msgEl.classList.remove('hidden');
          }
          if (typeof showToastNotification === 'function') {
            showToastNotification(errMsg);
          }
        }
      } catch (err) {
        console.error('USDT Deposit submit error:', err);
        const errMsg = tLang(
          l,
          'সার্ভার যোগাযোগে সমস্যা হয়েছে: ' + (err.message || 'Network Error'),
          'Server connection error: ' + (err.message || 'Network Error'),
          'خطأ في الاتصال بالخادم: ' + (err.message || 'Network Error')
        );
        if (msgEl) {
          msgEl.className = 'text-xs text-center font-semibold text-rose-400 py-1.5 bg-rose-500/10 rounded-lg border border-rose-500/30';
          msgEl.textContent = errMsg;
          msgEl.classList.remove('hidden');
        }
        if (typeof showToastNotification === 'function') {
          showToastNotification(errMsg);
        }
      } finally {
        submitBtn.disabled = false;
        if (btnSpinner) btnSpinner.classList.add('hidden');
        if (btnIcon) btnIcon.classList.remove('hidden');
        if (btnText) btnText.textContent = tLang(l, 'জমা দিন ও অটো এপ্রুভ করুন', 'Submit & Auto-Approve', 'إرسال والموافقة التلقائية');
      }
    };
  }

  // Render recent records on load
  renderRecentUsdtDeposits();
}
window.initUsdtDeposit = initUsdtDeposit;

// ==============================================================
// BANGLADESH ONLINE PAYMENT GATEWAY (bKash & Nagad via imcagro.top)
// ==============================================================
let selectedGatewayMethod = 'BKASH'; // 'BKASH' or 'NAGAD'

function setGatewayMethod(method) {
  selectedGatewayMethod = (method === 'NAGAD') ? 'NAGAD' : 'BKASH';
  const icon = document.getElementById('gateway-method-icon');
  const label = document.getElementById('gateway-method-label');
  const buttons = document.querySelectorAll('.gateway-switch-method-btn');
  const l = getActiveLang();

  if (selectedGatewayMethod === 'BKASH') {
    if (icon) {
      icon.className = 'w-7 h-7 rounded-full bg-[#e2136e] flex items-center justify-center text-white text-[11px] font-bold shadow';
      icon.textContent = 'bK';
    }
    if (label) label.textContent = tLang(l, 'বিকাশ (bKash)', 'bKash', 'bKash');
  } else {
    if (icon) {
      icon.className = 'w-7 h-7 rounded-full bg-[#f7931e] flex items-center justify-center text-white text-[11px] font-bold shadow';
      icon.textContent = l === 'bn' ? 'নগদ' : 'NG';
    }
    if (label) label.textContent = tLang(l, 'নগদ (Nagad)', 'Nagad', 'Nagad');
  }

  buttons.forEach(function(btn) {
    if (btn.dataset.method === selectedGatewayMethod) {
      const color = selectedGatewayMethod === 'BKASH' ? 'text-[#e2136e] bg-[#e2136e]/20 border-[#e2136e]/50' : 'text-[#f7931e] bg-[#f7931e]/20 border-[#f7931e]/50';
      btn.className = `gateway-switch-method-btn px-2.5 py-1 rounded-lg text-[10.5px] font-bold border transition cursor-pointer ${color}`;
    } else {
      btn.className = 'gateway-switch-method-btn px-2.5 py-1 rounded-lg text-[10.5px] font-bold border transition cursor-pointer bg-[#0e2a66] text-slate-300 border-[#1a3875] hover:text-white';
    }
  });
}
window.setGatewayMethod = setGatewayMethod;

async function handleGatewayPayNow() {
  const customInput = document.getElementById('gateway-custom-amount');
  const statusMsg = document.getElementById('gateway-pay-status-msg');
  const payBtn = document.getElementById('gateway-pay-now-btn');
  const btnSpinner = document.getElementById('gateway-btn-spinner');
  const btnText = document.getElementById('gateway-btn-text');
  const l = getActiveLang();

  const rawAmount = customInput ? parseFloat(customInput.value) : 0;
  const amount = Math.round(rawAmount);

  const minRcAmt = Number((window.aloPlatformConfig && window.aloPlatformConfig.minRecharge) || 126);

  // Validate: whole numbers only, minRecharge to 50000
  if (!amount || isNaN(amount) || amount < minRcAmt || amount > 50000) {
    if (statusMsg) {
      statusMsg.className = 'text-xs text-center font-semibold text-rose-400 py-2 bg-rose-500/10 rounded-lg border border-rose-500/30';
      statusMsg.textContent = tLang(
        l,
        `টাকার পরিমাণ অবশ্যই ${minRcAmt} থেকে ৫০,০০০ এর মধ্যে হতে হবে। (Min ${minRcAmt}, Max 50000 BDT)`,
        `Amount must be between ${minRcAmt} and 50,000 BDT.`,
        `يجب أن يكون المبلغ بين ${minRcAmt} و 50,000 BDT.`
      );
      statusMsg.classList.remove('hidden');
    }
    if (customInput) customInput.focus();
    return;
  }

  // Payment type in uppercase: BKASH or NAGAD
  const payType = (selectedGatewayMethod === 'NAGAD' ? 'NAGAD' : 'BKASH').toUpperCase();

  // Generate unique orderId: "ORD" + timestamp + 3 random digits
  const orderId = 'ORD' + Date.now() + Math.floor(100 + Math.random() * 900);

  // Loading state & double-submit prevention
  if (payBtn) payBtn.disabled = true;
  if (btnSpinner) btnSpinner.classList.remove('hidden');
  if (btnText) btnText.textContent = tLang(l, 'গেটওয়ে পেজে নিয়ে যাওয়া হচ্ছে...', 'Redirecting to gateway...', 'جاري التحويل إلى بوابة الدفع...');
  if (statusMsg) {
    statusMsg.className = 'text-xs text-center font-semibold text-sky-400 py-2 bg-sky-500/10 rounded-lg border border-sky-500/30 animate-pulse';
    statusMsg.textContent = tLang(l, 'পেমেন্ট গেটওয়ে লিংক প্রস্তুত হচ্ছে, অনুগ্রহ করে অপেক্ষা করুন...', 'Preparing payment gateway link, please wait...', 'جاري تجهيز رابط الدفع، يرجى الانتظار...');
    statusMsg.classList.remove('hidden');
  }

  // In cPanel (imcagro.top) or preview, route through the cPanel payment server
  const apiUrl = (window.location.hostname === 'imcagro.top' || window.location.hostname.endsWith('.imcagro.top'))
    ? 'https://imcagro.top/api/create-payment'
    : '/api/create-payment';

  const user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  const userPhone = user ? (user.phone || user.accountNumber || '') : '';

  try {
    localStorage.setItem('alo_pending_recharge_order', JSON.stringify({
      orderId: orderId,
      amount: amount,
      payType: payType,
      phone: userPhone,
      timestamp: Date.now()
    }));
  } catch (e) {}

  // Ensure pending deposit order exists immediately in local cache & Supabase
  if (userPhone) {
    const nowGw = new Date();
    const gwMethod = payType === 'NAGAD' ? 'নগদ (Nagad) [Auto]' : 'বিকাশ (bKash) [Auto]';
    const gwDate = nowGw.toISOString().split('T')[0];
    const gwTime = nowGw.toTimeString().split(' ')[0];
    if (typeof upsertLocalDepositOrder === 'function') {
      upsertLocalDepositOrder(userPhone, {
        orderId: orderId,
        type: 'deposit',
        amount: amount,
        actual: 0,
        ratio: '0%',
        status: 'মুলতবি (Pending)',
        method: gwMethod,
        date: gwDate,
        time: gwTime,
        createdAt: nowGw.toISOString()
      });
    }
    if (typeof renderAccountChangeHistory === 'function') renderAccountChangeHistory();
    if (window.aloSupabase) {
      try {
        await Promise.race([
          window.aloSupabase.from('transactions').insert({
            phone: normalizeBdPhone(userPhone),
            type: 'deposit',
            amount: amount,
            actual: 0,
            ratio: '0%',
            status: 'মুলতবি (Pending)',
            method: formatMethodWithOrderId(gwMethod, orderId),
            date: gwDate,
            time: gwTime,
            created_at: nowGw.toISOString()
          }),
          new Promise(function(resolve) { setTimeout(resolve, 1500); })
        ]);
      } catch (e) {}
    }
  }

  const payload = {
    amount: amount,
    orderId: orderId,
    payType: payType,
    phone: userPhone,
    attach: userPhone
  };

  try {
    const response = await fetch(apiUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(payload)
    });

    const data = await response.json();

    console.log('[Backend Payment Response]', data);

    // Check success & extract paymentUrl
    const paymentUrl = data.paymentUrl || 
                       data?.gatewayResponse?.data?.url || 
                       data?.data?.url || 
                       data?.url;

    if (data.success === true && paymentUrl) {
      if (statusMsg) {
        statusMsg.className = 'text-xs text-center font-bold text-emerald-400 py-2 bg-emerald-500/15 rounded-lg border border-emerald-500/30';
        statusMsg.textContent = tLang(l, '✅ সফল! পেমেন্ট ক্যাশিয়ার পেজে রিডাইরেক্ট করা হচ্ছে...', '✅ Success! Redirecting to payment cashier...', '✅ تم بنجاح! جاري التحويل إلى صفحة الدفع...');
      }
      // Redirect to the cashier URL returned by the backend
      window.location.href = paymentUrl;
      return;
    }

    // Failure: show gatewayResponse.msg or message
    const errMsg = data?.gatewayResponse?.msg || 
                   data?.message || 
                   data?.msg || 
                   (typeof data?.error === 'string' ? data.error : '') || 
                   tLang(l, 'পেমেন্ট লিংক পাওয়া যায়নি। অনুগ্রহ করে আবার চেষ্টা করুন।', 'Payment link not found. Please try again.', 'لم يتم العثور على رابط الدفع. يرجى المحاولة مرة أخرى.');

    if (statusMsg) {
      statusMsg.className = 'text-xs text-center font-semibold text-rose-400 py-2 bg-rose-500/10 rounded-lg border border-rose-500/30';
      statusMsg.textContent = tLang(l, 'পেমেন্ট ত্রুটি: ', 'Payment Error: ', 'خطأ في الدفع: ') + errMsg;
      statusMsg.classList.remove('hidden');
    }
    if (typeof showToastNotification === 'function') {
      showToastNotification(errMsg);
    }

  } catch (err) {
    console.error('Payment request error:', err);
    if (statusMsg) {
      statusMsg.className = 'text-xs text-center font-semibold text-rose-400 py-2 bg-rose-500/10 rounded-lg border border-rose-500/30';
      statusMsg.textContent = tLang(l, 'সার্ভার যোগাযোগে সমস্যা হয়েছে: ', 'Server connection error: ', 'خطأ في الاتصال بالخادم: ') + (err.message || 'Network Error');
      statusMsg.classList.remove('hidden');
    }
    if (typeof showToastNotification === 'function') {
      showToastNotification(tLang(l, 'পেমেন্ট সার্ভারে সংযোগ করা যায়নি।', 'Could not connect to payment server.', 'تعذر الاتصال بخادم الدفع.'));
    }
  } finally {
    if (payBtn) payBtn.disabled = false;
    if (btnSpinner) btnSpinner.classList.add('hidden');
    if (btnText) btnText.textContent = tLang(l, 'Pay Now (পেমেন্ট করুন) ⚡', 'Pay Now ⚡', 'ادفع الآن ⚡');
  }
}
window.handleGatewayPayNow = handleGatewayPayNow;

function initBdGatewayCheckout() {
  // Method switch buttons (bKash / Nagad)
  document.querySelectorAll('.gateway-switch-method-btn').forEach(function(btn) {
    btn.onclick = function(e) {
      e.preventDefault();
      setGatewayMethod(btn.dataset.method);
    };
  });

  // Quick Amount chips
  document.querySelectorAll('.gateway-quick-amt').forEach(function(btn) {
    btn.onclick = function(e) {
      e.preventDefault();
      const amt = parseFloat(btn.dataset.amount || '0');
      const input = document.getElementById('gateway-custom-amount');
      if (input && amt > 0) {
        input.value = amt;
      }
      document.querySelectorAll('.gateway-quick-amt').forEach(function(b) {
        b.classList.remove('ring-2', 'ring-[#35c6e7]', 'bg-[#1264c9]');
        b.classList.add('bg-[#0e2a66]');
      });
      btn.classList.add('ring-2', 'ring-[#35c6e7]', 'bg-[#1264c9]');
      btn.classList.remove('bg-[#0e2a66]');
    };
  });

  // Custom amount input listener
  const customInput = document.getElementById('gateway-custom-amount');
  if (customInput) {
    customInput.oninput = function() {
      const val = parseFloat(customInput.value || '0');
      document.querySelectorAll('.gateway-quick-amt').forEach(function(b) {
        if (parseFloat(b.dataset.amount || '0') === val) {
          b.classList.add('ring-2', 'ring-[#35c6e7]', 'bg-[#1264c9]');
          b.classList.remove('bg-[#0e2a66]');
        } else {
          b.classList.remove('ring-2', 'ring-[#35c6e7]', 'bg-[#1264c9]');
          b.classList.add('bg-[#0e2a66]');
        }
      });
    };
  }

  // Pay Now button
  const payBtn = document.getElementById('gateway-pay-now-btn');
  if (payBtn) {
    payBtn.onclick = function(e) {
      e.preventDefault();
      handleGatewayPayNow();
    };
  }
}
window.initBdGatewayCheckout = initBdGatewayCheckout;

